import { useState, useEffect } from 'react'

/**
 * Shared data freshness indicator component.
 * Shows relative time since last update with color-coded staleness.
 *
 * @param {string|Date} updatedAt - ISO string or Date of last update
 * @param {function} [onRefresh] - Optional refresh callback (renders button)
 * @param {boolean} [refreshing] - Whether refresh is in progress
 * @param {boolean} [compact] - Compact mode (dot + time only)
 */
export default function DataFreshness({ updatedAt, onRefresh, refreshing, compact }) {
  const [now, setNow] = useState(Date.now())

  // Tick every 30s to update relative time
  useEffect(() => {
    const timer = setInterval(() => setNow(Date.now()), 30000)
    return () => clearInterval(timer)
  }, [])

  if (!updatedAt) return null

  const ts = updatedAt instanceof Date ? updatedAt.getTime() : new Date(updatedAt).getTime()
  if (isNaN(ts)) return null

  const diffMs = now - ts
  const diffMin = Math.floor(diffMs / 60000)
  const diffHr = Math.floor(diffMin / 60)

  // Relative time in Korean
  let label
  if (diffMin < 1) label = '방금 전'
  else if (diffMin < 60) label = `${diffMin}분 전`
  else if (diffHr < 24) label = `${diffHr}시간 전`
  else label = `${Math.floor(diffHr / 24)}일 전`

  // Color by staleness
  let color
  if (diffMin < 5) color = '#22c55e'       // green: fresh
  else if (diffMin < 30) color = '#eab308'  // yellow: aging
  else if (diffMin < 60) color = '#f97316'  // orange: stale
  else color = '#ef4444'                    // red: very stale

  if (compact) {
    return (
      <span style={{ display: 'inline-flex', alignItems: 'center', gap: 4, fontSize: '0.65rem', color: 'var(--text-muted)' }}>
        <span style={{ width: 6, height: 6, borderRadius: '50%', background: color, display: 'inline-block', flexShrink: 0 }} />
        {label}
        {onRefresh && (
          <button
            onClick={onRefresh}
            disabled={refreshing}
            style={{ background: 'none', border: 'none', color: 'var(--text-muted)', cursor: 'pointer', padding: 0, fontSize: '0.7rem' }}
            title="새로고침"
          >
            {refreshing ? '⏳' : '↻'}
          </button>
        )}
      </span>
    )
  }

  return (
    <div style={{
      display: 'inline-flex', alignItems: 'center', gap: 6,
      fontSize: '0.7rem', color: 'var(--text-muted)',
      padding: '3px 8px', borderRadius: 6,
      background: `${color}11`, border: `1px solid ${color}33`,
    }}>
      <span style={{ width: 6, height: 6, borderRadius: '50%', background: color, display: 'inline-block', flexShrink: 0 }} />
      <span>{label} 갱신</span>
      {onRefresh && (
        <button
          onClick={onRefresh}
          disabled={refreshing}
          style={{
            background: 'none', border: 'none', cursor: 'pointer',
            color: 'var(--text-muted)', padding: '0 2px', fontSize: '0.75rem',
          }}
          title="새로고침"
        >
          {refreshing ? '⏳' : '↻'}
        </button>
      )}
    </div>
  )
}

/**
 * Hook to track data freshness with auto-stale detection.
 * Returns updatedAt timestamp and setter, plus isStale flag.
 *
 * @param {number} [staleMinutes=5] - Minutes before data is considered stale
 */
// eslint-disable-next-line react-refresh/only-export-components -- hook and component intentionally co-located
export function useDataFreshness(staleMinutes = 5) {
  const [updatedAt, setUpdatedAt] = useState(null)
  const [now, setNow] = useState(Date.now())

  useEffect(() => {
    const timer = setInterval(() => setNow(Date.now()), 30000)
    return () => clearInterval(timer)
  }, [])

  const isStale = updatedAt
    ? (now - (updatedAt instanceof Date ? updatedAt.getTime() : new Date(updatedAt).getTime())) > staleMinutes * 60000
    : true

  return { updatedAt, setUpdatedAt, isStale }
}

/**
 * PageGuide — Dismissible contextual guide shown at top of each page.
 *
 * Guides are dismissed per-page and remembered in localStorage.
 * Reset all: localStorage.removeItem('vibe_dismissed_guides')
 */
import { useState, useEffect } from 'react'

const STORAGE_KEY = 'vibe_dismissed_guides'

function getDismissed() {
  try {
    return JSON.parse(localStorage.getItem(STORAGE_KEY) || '{}')
  } catch {
    return {}
  }
}

export default function PageGuide({ pageId, title, steps, color = 'var(--accent)' }) {
  const [dismissed, setDismissed] = useState(true)

  useEffect(() => {
    const d = getDismissed()
    setDismissed(!!d[pageId])
  }, [pageId])

  const handleDismiss = () => {
    const d = getDismissed()
    d[pageId] = true
    localStorage.setItem(STORAGE_KEY, JSON.stringify(d))
    setDismissed(true)
  }

  if (dismissed || !steps?.length) return null

  return (
    <div style={{
      background: `linear-gradient(135deg, ${color}10, ${color}05)`,
      border: `1px solid ${color}30`,
      borderRadius: '0.75rem',
      padding: '0.85rem 1.25rem',
      marginBottom: '1.25rem',
      display: 'flex',
      alignItems: 'flex-start',
      gap: '1rem',
    }}>
      <span style={{ fontSize: '1.1rem', marginTop: '0.1rem' }}>{'💡'}</span>
      <div style={{ flex: 1 }}>
        {title && (
          <div style={{ fontWeight: 600, fontSize: '0.82rem', marginBottom: '0.35rem', color: 'var(--text-primary)' }}>
            {title}
          </div>
        )}
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: '0.4rem 1.25rem' }}>
          {steps.map((step, i) => (
            <span key={i} style={{ fontSize: '0.75rem', color: 'var(--text-secondary)', lineHeight: 1.5 }}>
              <span style={{ color, fontWeight: 600, marginRight: '0.3rem' }}>{i + 1}.</span>
              {step}
            </span>
          ))}
        </div>
      </div>
      <button
        onClick={handleDismiss}
        style={{
          background: 'none', border: 'none', color: 'var(--text-muted)',
          cursor: 'pointer', fontSize: '0.85rem', padding: '0.2rem',
          lineHeight: 1, flexShrink: 0,
        }}
        title="닫기 (다시 보려면 가이드 페이지 참고)"
      >
        {'✕'}
      </button>
    </div>
  )
}

import { useState, useEffect } from 'react'
import { getPriceChart, getSignalHistory } from '../api'
import {
  ComposedChart, Line, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, CartesianGrid
} from 'recharts'

export default function SymbolModal({ symbol, market, onClose }) {
  const [priceData, setPriceData] = useState([])
  const [signals, setSignals] = useState([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState(null)
  const [days, setDays] = useState(60)

  useEffect(() => {
    if (!symbol) return
    setLoading(true)
    Promise.all([
      getPriceChart(symbol, market, days),
      getSignalHistory(market, 90, symbol),
    ])
      .then(([priceRes, sigRes]) => {
        setPriceData(priceRes.data || [])
        setSignals(sigRes.signals || [])
        setError(null)
      })
      .catch(err => setError(err.message))
      .finally(() => setLoading(false))
  }, [symbol, market, days])

  // ESC key handler
  useEffect(() => {
    const handler = (e) => { if (e.key === 'Escape') onClose() }
    window.addEventListener('keydown', handler)
    return () => window.removeEventListener('keydown', handler)
  }, [onClose])

  if (!symbol) return null

  const latest = priceData.length > 0 ? priceData[priceData.length - 1] : null
  const latestSignal = signals.length > 0 ? signals[0] : null

  const formatPrice = (v) => {
    if (v == null) return '-'
    return market === 'KR' ? v.toLocaleString() : v.toFixed(2)
  }

  return (
    <div className="modal-overlay" onClick={onClose}>
      <div className="modal-content" onClick={e => e.stopPropagation()}>
        {/* Header */}
        <div className="modal-header">
          <div>
            <h3 style={{ fontSize: '1.25rem', fontWeight: 700 }}>
              {latestSignal?.name || symbol}
            </h3>
            <span style={{ fontSize: '0.8rem', color: 'var(--text-muted)' }}>
              {symbol} &middot; <span className={`badge badge-${market === 'KR' ? 'buy' : 'hold'}`}>{market}</span>
            </span>
          </div>
          <button className="modal-close" onClick={onClose}>&times;</button>
        </div>

        {loading ? (
          <div className="loading"><span className="spinner" /> Loading...</div>
        ) : error ? (
          <div style={{ color: 'var(--red)', padding: '1rem' }}>Error: {error}</div>
        ) : (
          <>
            {/* Day selector */}
            <div className="filter-bar" style={{ marginBottom: '0.75rem' }}>
              {[30, 60, 120, 200].map(d => (
                <button
                  key={d}
                  className={`btn btn-sm ${days === d ? 'btn-primary' : 'btn-outline'}`}
                  onClick={() => setDays(d)}
                >
                  {d}D
                </button>
              ))}
            </div>

            {/* Price + Volume Chart */}
            {priceData.length > 0 && (
              <div style={{ marginBottom: '1.25rem' }}>
                <ResponsiveContainer width="100%" height={300}>
                  <ComposedChart data={priceData}>
                    <CartesianGrid strokeDasharray="3 3" stroke="#334155" />
                    <XAxis
                      dataKey="trade_date"
                      tick={{ fill: '#94a3b8', fontSize: 10 }}
                      tickFormatter={v => v?.slice(5)}
                    />
                    <YAxis
                      yAxisId="price"
                      domain={['auto', 'auto']}
                      tick={{ fill: '#94a3b8', fontSize: 10 }}
                      tickFormatter={v => v != null ? (market === 'KR' ? (v / 1000).toFixed(0) + 'k' : v.toFixed(0)) : ''}
                    />
                    <YAxis
                      yAxisId="volume"
                      orientation="right"
                      tick={{ fill: '#475569', fontSize: 9 }}
                      tickFormatter={v => v != null ? (v >= 1000000 ? `${(v / 1000000).toFixed(0)}M` : `${(v / 1000).toFixed(0)}K`) : ''}
                      domain={[0, dataMax => dataMax * 3]}
                    />
                    <Tooltip
                      contentStyle={{ background: '#1e293b', border: '1px solid #334155', fontSize: '0.8rem' }}
                      formatter={(v, name) => {
                        if (name === 'volume') return [v >= 1000000 ? `${(v / 1000000).toFixed(1)}M` : `${(v / 1000).toFixed(0)}K`, '거래량']
                        return [formatPrice(v), name === 'close' ? '종가' : name === 'high' ? '고가' : name === 'low' ? '저가' : name]
                      }}
                      labelFormatter={(l) => l}
                    />
                    <Bar
                      yAxisId="volume"
                      dataKey="volume"
                      fill="rgba(59,130,246,0.15)"
                      radius={[1, 1, 0, 0]}
                    />
                    <Line
                      yAxisId="price"
                      type="monotone"
                      dataKey="close"
                      stroke="var(--accent)"
                      strokeWidth={2}
                      dot={false}
                    />
                  </ComposedChart>
                </ResponsiveContainer>
              </div>
            )}

            {/* Key Indicators */}
            <div className="card-grid" style={{ gridTemplateColumns: 'repeat(3, 1fr)', marginBottom: '1.25rem' }}>
              <div className="card" style={{ padding: '0.75rem' }}>
                <div className="card-label">Latest Close</div>
                <div className="card-value blue" style={{ fontSize: '1.25rem' }}>
                  {market === 'KR' ? '₩' : '$'}{formatPrice(latest?.close)}
                </div>
                <div className="card-sub">{latest?.trade_date}</div>
              </div>
              <div className="card" style={{ padding: '0.75rem' }}>
                <div className="card-label">RSI</div>
                <div className={`card-value ${(latestSignal?.rsi_value || 0) > 65 ? 'red' : (latestSignal?.rsi_value || 0) > 50 ? 'yellow' : 'green'}`} style={{ fontSize: '1.25rem' }}>
                  {latestSignal?.rsi_value?.toFixed(1) || 'N/A'}
                </div>
              </div>
              <div className="card" style={{ padding: '0.75rem' }}>
                <div className="card-label">Volume</div>
                <div className="card-value blue" style={{ fontSize: '1.25rem' }}>
                  {latest?.volume ? (latest.volume >= 1000000 ? `${(latest.volume / 1000000).toFixed(1)}M` : `${(latest.volume / 1000).toFixed(0)}K`) : 'N/A'}
                </div>
              </div>
            </div>

            {/* Recent Signals Table */}
            {signals.length > 0 && (
              <div className="table-container" style={{ marginBottom: 0 }}>
                <div className="table-header">
                  <h3>Recent Signals</h3>
                  <span className="card-sub">{signals.length} signals</span>
                </div>
                <table>
                  <thead>
                    <tr>
                      <th>Date</th>
                      <th>Signal</th>
                      <th>Score</th>
                      <th>RSI</th>
                      <th>Rationale</th>
                    </tr>
                  </thead>
                  <tbody>
                    {signals.slice(0, 10).map((s, i) => (
                      <tr key={`${s.signal_date}-${i}`}>
                        <td style={{ whiteSpace: 'nowrap' }}>{s.signal_date}</td>
                        <td>
                          <span className={`badge badge-${s.final_signal?.toLowerCase()}`}>
                            {s.final_signal}
                          </span>
                        </td>
                        <td style={{ color: s.raw_score > 0 ? 'var(--green)' : s.raw_score < 0 ? 'var(--red)' : '' }}>
                          {s.raw_score?.toFixed(1)}
                        </td>
                        <td>{s.rsi_value?.toFixed(1)}</td>
                        <td style={{ maxWidth: 200, fontSize: '0.75rem', color: 'var(--text-secondary)' }}>
                          {s.explanation_rule || s.rationale?.slice(0, 60) || '-'}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}

            {signals.length === 0 && (
              <div style={{ padding: '1rem', color: 'var(--text-muted)', textAlign: 'center' }}>
                No signal data for this symbol
              </div>
            )}
          </>
        )}
      </div>
    </div>
  )
}

/**
 * Tip — Lightweight hover tooltip component.
 *
 * Usage:
 *   <Tip text="설명 텍스트">
 *     <span>호버 대상</span>
 *   </Tip>
 *
 * Or inline with a dotted underline indicator:
 *   <Tip text="설명" indicator>RSI</Tip>
 */
import { useState, useRef, useEffect, useCallback } from 'react'

const STYLES = {
  wrapper: {
    position: 'relative',
    display: 'inline-flex',
    alignItems: 'center',
    cursor: 'help',
  },
  indicator: {
    borderBottom: '1px dotted rgba(148,163,184,0.5)',
  },
  bubble: {
    position: 'fixed',
    zIndex: 9999,
    maxWidth: '320px',
    minWidth: '160px',
    padding: '0.6rem 0.8rem',
    borderRadius: '0.5rem',
    background: '#1e293b',
    border: '1px solid #475569',
    boxShadow: '0 8px 24px rgba(0,0,0,0.4)',
    color: '#e2e8f0',
    fontSize: '0.78rem',
    lineHeight: 1.55,
    pointerEvents: 'none',
    whiteSpace: 'pre-line',
  },
  arrow: {
    position: 'absolute',
    width: '8px',
    height: '8px',
    background: '#1e293b',
    border: '1px solid #475569',
    transform: 'rotate(45deg)',
    zIndex: -1,
  },
}

export default function Tip({ text, children, indicator = false, placement = 'top' }) {
  const [show, setShow] = useState(false)
  const [pos, setPos] = useState({ top: 0, left: 0, arrowStyle: {} })
  const wrapperRef = useRef(null)
  const bubbleRef = useRef(null)
  const timerRef = useRef(null)

  const computePosition = useCallback(() => {
    if (!wrapperRef.current || !bubbleRef.current) return
    const triggerRect = wrapperRef.current.getBoundingClientRect()
    const bubbleRect = bubbleRef.current.getBoundingClientRect()
    const gap = 8

    let top, left, arrowStyle = {}

    // Try preferred placement, fall back if off-screen
    if (placement === 'top' && triggerRect.top - bubbleRect.height - gap > 10) {
      top = triggerRect.top - bubbleRect.height - gap
      left = triggerRect.left + triggerRect.width / 2 - bubbleRect.width / 2
      arrowStyle = {
        bottom: '-5px',
        left: '50%',
        marginLeft: '-4px',
        borderTop: 'none',
        borderLeft: 'none',
      }
    } else {
      // Bottom fallback
      top = triggerRect.bottom + gap
      left = triggerRect.left + triggerRect.width / 2 - bubbleRect.width / 2
      arrowStyle = {
        top: '-5px',
        left: '50%',
        marginLeft: '-4px',
        borderBottom: 'none',
        borderRight: 'none',
      }
    }

    // Clamp horizontal to viewport
    const vw = window.innerWidth
    if (left < 10) left = 10
    if (left + bubbleRect.width > vw - 10) left = vw - bubbleRect.width - 10

    setPos({ top, left, arrowStyle })
  }, [placement])

  const handleEnter = () => {
    timerRef.current = setTimeout(() => setShow(true), 200)
  }
  const handleLeave = () => {
    clearTimeout(timerRef.current)
    setShow(false)
  }

  useEffect(() => {
    if (show) computePosition()
  }, [show, computePosition])

  useEffect(() => {
    return () => clearTimeout(timerRef.current)
  }, [])

  if (!text) return children

  return (
    <span
      ref={wrapperRef}
      style={{ ...STYLES.wrapper, ...(indicator ? STYLES.indicator : {}) }}
      onMouseEnter={handleEnter}
      onMouseLeave={handleLeave}
      onFocus={handleEnter}
      onBlur={handleLeave}
    >
      {children}
      {show && (
        <div ref={bubbleRef} style={{ ...STYLES.bubble, top: pos.top, left: pos.left }}>
          <div style={{ ...STYLES.arrow, ...pos.arrowStyle }} />
          {text}
        </div>
      )}
    </span>
  )
}

import { useState, useEffect, useCallback } from 'react'
import { getAcademyToday, getAcademyConcepts, getAcademyConcept, getAcademyPatterns } from '../api'
import HelpButton from '../components/HelpButton'
import PageGuide from '../components/PageGuide'
import { useToast } from '../components/Toast'
import Tip from '../components/Tip'

const DIFFICULTY_LABELS = { 1: '⭐ 입문', 2: '⭐⭐ 중급', 3: '⭐⭐⭐ 심화' }
const ZONE_COLORS = { safe: '#22c55e', warning: '#f59e0b', danger: '#ef4444', neutral: '#94a3b8' }

export default function Academy({ onNavigate, refreshKey }) {
  const toast = useToast()
  const [todayLesson, setTodayLesson] = useState(null)
  const [categories, setCategories] = useState([])
  const [patterns, setPatterns] = useState([])
  const [selectedConcept, setSelectedConcept] = useState(null)
  const [conceptDetail, setConceptDetail] = useState(null)
  const [loading, setLoading] = useState(true)
  const [tab, setTab] = useState('today') // today | concepts | patterns

  const loadData = useCallback(() => {
    setLoading(true)
    Promise.all([
      getAcademyToday().catch(() => null),
      getAcademyConcepts().catch(() => ({ categories: [] })),
      getAcademyPatterns().catch(() => ({ patterns: [] })),
    ])
      .then(([today, cats, pats]) => {
        setTodayLesson(today)
        setCategories(cats?.categories || [])
        setPatterns(pats?.patterns || [])
      })
      .catch(() => toast.error('아카데미 데이터 로드 실패'))
      .finally(() => setLoading(false))
  }, [toast])

  useEffect(() => { loadData() }, [loadData, refreshKey])

  const openConcept = async (id) => {
    try {
      const detail = await getAcademyConcept(id)
      setConceptDetail(detail)
      setSelectedConcept(id)
    } catch { toast.error('개념 로드 실패') }
  }

  if (loading) return <div className="loading"><span className="spinner" /> 로딩 중...</div>

  return (
    <div>
      <div className="page-header">
        <div>
          <h2>{'🎓'} 투자 아카데미</h2>
          <p className="subtitle">{'현재 시장을 통해 배우는 투자 지식'}</p>
        </div>
        <div style={{ display: 'flex', gap: '0.5rem', alignItems: 'center' }}>
          <button className="btn btn-outline" onClick={loadData}>{'↻'} Refresh</button>
          <HelpButton section="academy" onNavigate={onNavigate} />
        </div>
      </div>

      <PageGuide
        pageId="academy"
        title="투자 아카데미 활용법"
        steps={[
          '오늘의 레슨 → 현재 시장 상황 맞춤 교육 콘텐츠',
          '개념 사전 → RSI, 볼린저밴드 등 핵심 지표 해설',
          '역사적 패턴 → 과거 위기/랠리 사례와 교훈',
          '색상 구간 → 녹색(안전), 노랑(주의), 빨강(위험)',
        ]}
        color="#8b5cf6"
      />

      {/* Tab Navigation */}
      <div style={{ display: 'flex', gap: '0.5rem', marginBottom: '1.5rem' }}>
        {[
          ['today', '📚 오늘의 레슨', TIPS.tab_today],
          ['concepts', '📖 개념 사전', TIPS.tab_concepts],
          ['patterns', '🔍 역사적 패턴', TIPS.tab_patterns],
        ].map(([key, label, tipText]) => (
          <Tip key={key} text={tipText}>
            <button className={`btn ${tab === key ? 'btn-primary' : 'btn-outline'}`}
              onClick={() => { setTab(key); setSelectedConcept(null) }}>
              {label}
            </button>
          </Tip>
        ))}
      </div>

      {/* Today's Lesson Tab */}
      {tab === 'today' && todayLesson && (
        <>
          {/* Why Now Banner */}
          {todayLesson.lesson?.why_now_kr && (
            <div style={{
              background: 'rgba(59,130,246,0.08)', border: '1px solid rgba(59,130,246,0.3)',
              borderRadius: '0.75rem', padding: '1.25rem', marginBottom: '1.5rem',
            }}>
              <div style={{ fontSize: '0.8rem', color: 'var(--blue)', fontWeight: 600, marginBottom: '0.5rem' }}>
                <Tip text={TIPS.why_now} indicator>
                  {'💡'} {'오늘 이 개념을 배우는 이유'}
                </Tip>
              </div>
              <div style={{ color: 'var(--text-secondary)', fontSize: '0.9rem', lineHeight: 1.6 }}>
                {todayLesson.lesson.why_now_kr}
              </div>
            </div>
          )}

          {/* Concept Card */}
          {todayLesson.lesson?.concept && renderConceptCard(todayLesson.lesson.concept, todayLesson.lesson.current_value, todayLesson.lesson.current_status)}

          {/* Historical Patterns */}
          {todayLesson.historical_patterns?.length > 0 && (
            <div className="card" style={{ marginTop: '1.5rem' }}>
              <h3 style={{ marginBottom: '1rem' }}>
                {'🔍'}{' '}
                <Tip text={TIPS.similar_patterns} indicator>{'현재와 유사한 역사적 사례'}</Tip>
              </h3>
              {todayLesson.historical_patterns.map((p, i) => renderPatternCard(p, i))}
            </div>
          )}
        </>
      )}

      {/* Concepts Dictionary Tab */}
      {tab === 'concepts' && !selectedConcept && (
        <div>
          {categories.map((cat, ci) => (
            <div key={ci} className="card" style={{ marginBottom: '1rem' }}>
              <h3 style={{ marginBottom: '0.75rem' }}>
                <Tip text={TIPS.category_desc[cat.category] || '해당 카테고리의 투자 개념들.'} indicator>
                  {cat.category_kr}
                </Tip>
              </h3>
              <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(200px, 1fr))', gap: '0.5rem' }}>
                {cat.concepts?.map((c) => (
                  <button key={c.id} className="btn btn-outline" onClick={() => openConcept(c.id)}
                    style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', justifyContent: 'flex-start', textAlign: 'left', padding: '0.75rem' }}>
                    <span style={{ fontSize: '1.2rem' }}>{c.icon}</span>
                    <div>
                      <div style={{ fontWeight: 600, fontSize: '0.85rem' }}>{c.name_kr}</div>
                      <div style={{ fontSize: '0.7rem', color: 'var(--text-muted)' }}>
                        <Tip text={TIPS.difficulty[c.difficulty] || ''}>
                          <span>{DIFFICULTY_LABELS[c.difficulty]}</span>
                        </Tip>
                      </div>
                    </div>
                  </button>
                ))}
              </div>
            </div>
          ))}
        </div>
      )}

      {/* Concept Detail */}
      {tab === 'concepts' && selectedConcept && conceptDetail && (
        <div>
          <button className="btn btn-outline" onClick={() => setSelectedConcept(null)} style={{ marginBottom: '1rem' }}>
            {'←'} {'목록으로'}
          </button>
          {renderConceptCard(conceptDetail, conceptDetail.current_value, conceptDetail.current_label)}
        </div>
      )}

      {/* Historical Patterns Tab */}
      {tab === 'patterns' && (
        <div>
          {patterns.length === 0 ? (
            <div className="card" style={{ textAlign: 'center', padding: '2rem', color: 'var(--text-muted)' }}>
              {'현재 시장 조건과 유사한 역사적 패턴이 없습니다. 시장이 안정적인 상태입니다.'}
            </div>
          ) : (
            patterns.map((p, i) => renderPatternCard(p, i))
          )}
        </div>
      )}
    </div>
  )
}

function renderConceptCard(concept, currentValue, currentLabel) {
  return (
    <div className="card">
      <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem', marginBottom: '1rem' }}>
        <span style={{ fontSize: '2rem' }}>{concept.icon}</span>
        <div>
          <h3 style={{ margin: 0, fontSize: '1.1rem' }}>{concept.name_kr}</h3>
          <div style={{ fontSize: '0.8rem', color: 'var(--text-muted)' }}>{concept.name_en}</div>
        </div>
        {concept.difficulty && (
          <Tip text={TIPS.difficulty[concept.difficulty] || ''}>
            <span style={{ marginLeft: 'auto', fontSize: '0.75rem', color: 'var(--text-muted)' }}>
              {DIFFICULTY_LABELS[concept.difficulty]}
            </span>
          </Tip>
        )}
      </div>

      {/* Current Value */}
      {currentValue != null && (
        <div style={{
          background: 'rgba(59,130,246,0.06)', borderRadius: '0.5rem',
          padding: '0.75rem 1rem', marginBottom: '1rem', display: 'flex',
          alignItems: 'center', justifyContent: 'space-between',
        }}>
          <Tip text={TIPS.current_value}>
            <span style={{ fontWeight: 600, color: 'var(--text-primary)' }}>
              {'현재 값'}: {typeof currentValue === 'number' ? currentValue.toLocaleString() : currentValue}
            </span>
          </Tip>
          <Tip text={TIPS.current_status}>
            <span className={`badge badge-${currentLabel === '정상' || currentLabel === '완만한 정상' ? 'completed' : currentLabel?.includes('공포') || currentLabel?.includes('역전') ? 'sell' : 'hold'}`}>
              {currentLabel || '-'}
            </span>
          </Tip>
        </div>
      )}

      {/* Definition */}
      <div style={{ color: 'var(--text-secondary)', lineHeight: 1.8, fontSize: '0.9rem', marginBottom: '1rem' }}>
        {concept.definition_kr}
      </div>

      {/* Ranges */}
      {concept.ranges?.length > 0 && (
        <div style={{ marginBottom: '1rem' }}>
          <div style={{ fontWeight: 600, fontSize: '0.85rem', marginBottom: '0.5rem', color: 'var(--text-primary)' }}>
            <Tip text={TIPS.ranges_table} indicator>{'해석 기준'}</Tip>
          </div>
          <div className="table-responsive">
            <table>
              <thead>
                <tr>
                  <th><Tip text={TIPS.range_col} indicator>{'범위'}</Tip></th>
                  <th>{'레이블'}</th>
                  <th>{'의미'}</th>
                </tr>
              </thead>
              <tbody>
                {concept.ranges.map((r, i) => (
                  <tr key={i}>
                    <td style={{ fontWeight: 600, whiteSpace: 'nowrap' }}>{r.range}</td>
                    <td><span className="badge badge-hold">{r.label}</span></td>
                    <td style={{ fontSize: '0.85rem', color: 'var(--text-secondary)' }}>{r.meaning_kr}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* Key Insight */}
      {concept.key_insight_kr && (
        <div style={{
          background: 'rgba(245,158,11,0.08)', border: '1px solid rgba(245,158,11,0.2)',
          borderRadius: '0.5rem', padding: '1rem',
        }}>
          <div style={{ fontWeight: 600, fontSize: '0.85rem', color: '#f59e0b', marginBottom: '0.4rem' }}>
            <Tip text={TIPS.key_insight} indicator>
              {'💡'} Key Insight
            </Tip>
          </div>
          <div style={{ color: 'var(--text-secondary)', fontSize: '0.85rem', lineHeight: 1.7 }}>
            {concept.key_insight_kr}
          </div>
        </div>
      )}
    </div>
  )
}

function renderPatternCard(pattern, index) {
  return (
    <div key={index} style={{
      padding: '1rem', marginBottom: '0.75rem',
      background: 'var(--bg-primary)', borderRadius: '0.5rem',
      border: '1px solid var(--border)',
    }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: '0.5rem' }}>
        <div>
          <div style={{ fontWeight: 700, fontSize: '1rem', color: 'var(--text-primary)' }}>
            {pattern.name_kr}
          </div>
          <div style={{ fontSize: '0.8rem', color: 'var(--text-muted)' }}>
            {pattern.period} | {pattern.trigger_kr}
          </div>
        </div>
        {pattern.match_score && (
          <Tip text={TIPS.match_score}>
            <span className={`badge ${pattern.match_score >= 60 ? 'badge-sell' : 'badge-hold'}`}>
              {'유사도'} {pattern.match_score}%
            </span>
          </Tip>
        )}
      </div>

      <div style={{ display: 'flex', gap: '1.5rem', marginBottom: '0.75rem', flexWrap: 'wrap' }}>
        <Tip text={TIPS.vix_peak}>
          <div style={{ fontSize: '0.8rem' }}>
            <span style={{ color: 'var(--text-muted)' }}>VIX Peak: </span>
            <span style={{ fontWeight: 600 }}>{pattern.vix_peak}</span>
          </div>
        </Tip>
        <Tip text={TIPS.fg_low}>
          <div style={{ fontSize: '0.8rem' }}>
            <span style={{ color: 'var(--text-muted)' }}>F&G Low: </span>
            <span style={{ fontWeight: 600 }}>{pattern.fg_low}</span>
          </div>
        </Tip>
        <Tip text={TIPS.sp500_drop}>
          <div style={{ fontSize: '0.8rem' }}>
            <span style={{ color: 'var(--text-muted)' }}>S&P 500: </span>
            <span style={{ fontWeight: 600, color: 'var(--red)' }}>{pattern.sp500_drop}%</span>
          </div>
        </Tip>
        <Tip text={TIPS.recovery}>
          <div style={{ fontSize: '0.8rem' }}>
            <span style={{ color: 'var(--text-muted)' }}>{'회복'}: </span>
            <span style={{ fontWeight: 600 }}>{pattern.recovery_months}{'개월'}</span>
          </div>
        </Tip>
      </div>

      {pattern.match_reasons?.length > 0 && (
        <Tip text={TIPS.match_reasons}>
          <div style={{ fontSize: '0.8rem', color: 'var(--blue)', marginBottom: '0.5rem' }}>
            {'유사 조건'}: {pattern.match_reasons.join(', ')}
          </div>
        </Tip>
      )}

      <div style={{
        background: 'rgba(34,197,94,0.06)', borderRadius: '0.4rem',
        padding: '0.75rem', fontSize: '0.85rem', color: 'var(--text-secondary)', lineHeight: 1.6,
      }}>
        <Tip text={TIPS.lesson}>
          <span>{'📝'}</span>
        </Tip>{' '}
        {pattern.lesson_kr}
      </div>
    </div>
  )
}

