export default function Guide({ onNavigate, initialSection }) {
  const [activeSection, setActiveSection] = useState(
    initialSection && sections.find(s => s.id === initialSection) ? initialSection : 'quickstart'
  )

  useEffect(() => {
    if (initialSection && sections.find(s => s.id === initialSection)) {
      setActiveSection(initialSection)
    }
  }, [initialSection])

  const active = sections.find(s => s.id === activeSection) || sections[0]

  // Pages that have a corresponding navigation target
  const navigablePages = new Set(['overview', 'signals', 'portfolio', 'backtest', 'market-brief', 'macro', 'fund-flow', 'screening', 'risk', 'system'])

  return (
    <div>
      <div className="page-header">
        <div>
          <h2>{'📖'} 사용 가이드</h2>
          <p className="subtitle">VIBE 대시보드 기능별 매뉴얼</p>
        </div>
      </div>

      {/* Section Tabs */}
      <div className="guide-tabs">
        {sections.map(s => (
          <button
            key={s.id}
            className={`guide-tab ${activeSection === s.id ? 'active' : ''}`}
            onClick={() => setActiveSection(s.id)}
          >
            <span className="guide-tab-icon">{s.icon}</span>
            {s.title}
          </button>
        ))}
      </div>

      {/* Section Content */}
      <div className="guide-content">
        <div className="guide-section-header">
          <span className="guide-section-icon">{active.icon}</span>
          <h3>{active.title}</h3>
        </div>

        {active.content.map((block, i) => (
          <div key={i} className="guide-block">
            <h4 className="guide-block-title">{block.heading}</h4>
            {block.text && <p className="guide-block-text">{block.text}</p>}
            {block.items && (
              <ul className="guide-list">
                {block.items.map((item, j) => {
                  const [label, ...rest] = item.split(' — ')
                  return (
                    <li key={j}>
                      {rest.length > 0
                        ? <><strong>{label}</strong> — {rest.join(' — ')}</>
                        : item
                      }
                    </li>
                  )
                })}
              </ul>
            )}
          </div>
        ))}

        {/* Quick nav to related page */}
        {navigablePages.has(active.id) && (
          <div className="guide-nav-hint">
            <button
              className="btn btn-outline"
              onClick={() => onNavigate && onNavigate(active.id)}
            >
              {active.icon} {active.title} 페이지로 이동 {'→'}
            </button>
          </div>
        )}
      </div>
    </div>
  )
}

import { useState, useEffect, useCallback } from 'react'
import { getMacroRegime, getStagflation, getCrossMarket, getMacroTrends,
  getMarketSeason, getInvestmentClock, getYieldPhase, getUnifiedRiskScore,
  getFearGauge, getEntryScenarios, getSectorMacroImpact,
  getCapitulationScan, getCrisisHedge } from '../api'
import {
  LineChart, Line, XAxis, YAxis, Tooltip, ResponsiveContainer,
  CartesianGrid, Legend, RadarChart, Radar, PolarGrid,
  PolarAngleAxis, PolarRadiusAxis, BarChart, Bar, Cell
} from 'recharts'
import HelpButton from '../components/HelpButton'
import PageGuide from '../components/PageGuide'
import { useToast } from '../components/Toast'

const REGIME_COLORS = {
  'Risk-On': '#22c55e', 'Risk-Off': '#ef4444', 'Panic': '#dc2626', 'Complacent': '#eab308',
}
const STAG_COLORS = { 'Low': '#22c55e', 'Watch': '#eab308', 'Elevated': '#f97316', 'High': '#ef4444' }
const REC_COLORS = {
  'KR Favorable': '#3b82f6', 'US Favorable': '#a855f7', 'Both OK': '#22c55e', 'Caution': '#ef4444',
}
const RISK_LEVEL_COLORS = {
  'Low': '#22c55e', 'Moderate': '#3b82f6', 'Elevated': '#f97316', 'High': '#ef4444', 'Critical': '#dc2626',
}
const YIELD_PHASE_COLORS = {
  'Normal': '#22c55e', 'Flattening': '#eab308', 'Inverted': '#ef4444',
  'Normalizing': '#dc2626', 'Transitioning': '#3b82f6', 'Unknown': '#64748b',
}
const FEAR_PHASE_COLORS = {
  'Calm': '#22c55e', 'Initial Panic': '#f59e0b', 'Peak Fear': '#ef4444', 'Post-Peak': '#3b82f6',
}
const FEAR_PHASE_ICONS = {
  'Calm': '\u{1F7E2}', 'Initial Panic': '\u{1F7E1}', 'Peak Fear': '\u{1F534}', 'Post-Peak': '\u{1F535}',
}

export default function Macro({ onNavigate, refreshKey }) {
  const toast = useToast()
  const [regime, setRegime] = useState(null)
  const [stagflation, setStagflation] = useState(null)
  const [crossMarket, setCrossMarket] = useState(null)
  const [trends, setTrends] = useState([])
  const [season, setSeason] = useState(null)
  const [clock, setClock] = useState(null)
  const [yieldPhase, setYieldPhase] = useState(null)
  const [riskScore, setRiskScore] = useState(null)
  const [fearGauge, setFearGauge] = useState(null)
  const [entryScenarios, setEntryScenarios] = useState(null)
  const [sectorImpact, setSectorImpact] = useState(null)
  const [capitulation, setCapitulation] = useState(null)
  const [crisisHedge, setCrisisHedge] = useState(null)
  const [loading, setLoading] = useState(true)
  const [trendDays, setTrendDays] = useState(30)

  const loadData = useCallback(() => {
    setLoading(true)
    return Promise.all([
      getMacroRegime().catch(() => null),
      getStagflation().catch(() => null),
      getCrossMarket().catch(() => null),
      getMarketSeason().catch(() => null),
      getInvestmentClock().catch(() => null),
      getYieldPhase().catch(() => null),
      getUnifiedRiskScore().catch(() => null),
      getFearGauge().catch(() => null),
      getEntryScenarios().catch(() => null),
      getSectorMacroImpact().catch(() => null),
      getCapitulationScan('KR').catch(() => null),
      getCrisisHedge(20).catch(() => null),
    ])
      .then(([r, s, cm, sea, clk, yp, rs, fg, es, si, cap, hedge]) => {
        setRegime(r); setStagflation(s); setCrossMarket(cm)
        setSeason(sea); setClock(clk); setYieldPhase(yp); setRiskScore(rs)
        setFearGauge(fg); setEntryScenarios(es); setSectorImpact(si)
        setCapitulation(cap); setCrisisHedge(hedge)
      })
      .catch(err => toast.error('Load failed: ' + err.message))
      .finally(() => setLoading(false))
  }, [])

  useEffect(() => { loadData() }, [loadData, refreshKey])

  // Fetch trends separately so changing trendDays doesn't reload all 12 other APIs
  useEffect(() => {
    getMacroTrends(trendDays).catch(() => ({ trends: [] }))
      .then(t => setTrends(t?.trends || []))
  }, [trendDays, refreshKey])

  if (loading) return <div className="loading"><span className="spinner" /> 로딩 중...</div>

  const risk = regime?.risk_regime || {}
  const driver = regime?.driver_regime || {}
  const stag = stagflation || {}
  const cm = crossMarket || {}

  // Radar chart data for cross-market comparison
  const radarData = cm.factors ? Object.entries(cm.factors).map(([key, f]) => ({
    factor: key === 'fx_trend' ? 'FX' : key === 'volatility' ? 'VIX' : key === 'yield_env' ? 'Yield' : key === 'fund_flow' ? 'Flow' : 'Signal',
    KR: Math.round(((f.kr_impact || 0) + 1) * 50),
    US: Math.round(((f.us_impact || 0) + 1) * 50),
  })) : []

  // Stagflation component bar data
  const stagBars = stag.components ? Object.entries(stag.components).map(([key, c]) => ({
    name: key === 'gold_copper_ratio' ? 'Gold/Copper' : key === 'yield_curve' ? 'Yield Curve' : key === 'oil_pressure' ? 'Oil' : key === 'dxy_tightening' ? 'DXY' : 'Copper',
    score: c.score || 0,
    weight: (c.weight || 0) * 100,
  })) : []

  return (
    <div>
      <div className="page-header">
        <div>
          <h2>{'🌐'} 매크로 인텔리전스</h2>
          <p className="subtitle">시장 레짐, 스태그플레이션 모니터링, 교차시장 분석</p>
        </div>
        <div style={{ display: 'flex', gap: '0.5rem', alignItems: 'center' }}>
          <button className="btn btn-outline" onClick={loadData}>{'↻'} Refresh</button>
          <HelpButton section="macro" onNavigate={onNavigate} />
        </div>
      </div>

      <PageGuide
        pageId="macro"
        title="이 페이지에서 확인할 것"
        steps={[
          'Market Season → 지금 봄/여름/가을/겨울 중 어디?',
          '리스크 점수 → 60 이상이면 방어 모드 전환 고려',
          'Fear Gauge → Peak Fear 시 역발상 매수 기회',
          'Entry Scenarios → KOSPI/SPY 지지·저항 참조선',
        ]}
        color="#f59e0b"
      />

      {/* Quick navigation to related pages */}
      <div style={{ display: 'flex', gap: '0.5rem', marginBottom: '1rem' }}>
        <button
          className="btn btn-outline"
          onClick={() => onNavigate('carry-trade')}
          style={{ fontSize: '0.75rem', padding: '0.3rem 0.75rem' }}
        >
          {'💱'} 캐리트레이드 분석
        </button>
        <button
          className="btn btn-outline"
          onClick={() => onNavigate('forex-map')}
          style={{ fontSize: '0.75rem', padding: '0.3rem 0.75rem' }}
        >
          {'🗺'} 환율 세계지도
        </button>
      </div>

      {/* ── Phase J: Market Season + Investment Clock + Yield Phase + Risk Score ── */}
      <div className="card-grid" style={{ gridTemplateColumns: 'repeat(4, 1fr)', marginBottom: '1rem' }}>
        {/* Market Season */}
        <div className="card" style={{ borderLeft: '3px solid #f59e0b', textAlign: 'center' }}>
          <div className="card-label">Market Season</div>
          <div style={{ fontSize: '2rem', lineHeight: 1.2 }}>{season?.icon || '❓'}</div>
          <div className="card-value" style={{ fontSize: '1.1rem', color: '#f59e0b' }}>
            {season?.season_kr || '-'}
          </div>
          <div style={{ fontSize: '0.7rem', color: 'var(--text-muted)', marginTop: '0.25rem' }}>
            {season?.season || '-'} / Conf: {season?.confidence ?? '-'}
          </div>
          {season?.strategy_kr && (
            <div style={{ fontSize: '0.7rem', color: 'var(--text-secondary)', marginTop: '0.3rem',
              padding: '0.2rem 0.4rem', background: 'rgba(245,158,11,0.08)', borderRadius: '4px' }}>
              {season.strategy_kr}
            </div>
          )}
          {season?.season_hint && (
            <div style={{ fontSize: '0.65rem', color: '#f59e0b', marginTop: '0.25rem' }}>
              {'ℹ️'} 추정: {season.season_hint_kr || season.season_hint}
            </div>
          )}
          {season?.data_days != null && season.data_days < 20 && (
            <div style={{ fontSize: '0.6rem', color: 'var(--text-muted)', marginTop: '0.15rem' }}>
              데이터 {season.data_days}일 (20일 미만 — 신뢰도 제한)
            </div>
          )}
        </div>

        {/* Investment Clock */}
        <div className="card" style={{ borderLeft: `3px solid ${clock?.color || '#64748b'}`, textAlign: 'center' }}>
          <div className="card-label">Investment Clock</div>
          <div className="card-value" style={{ fontSize: '1.1rem', color: clock?.color || 'var(--text-primary)' }}>
            {clock?.quadrant_kr || '-'}
          </div>
          <div style={{ fontSize: '0.7rem', color: 'var(--text-muted)', marginTop: '0.25rem' }}>
            성장: {clock?.growth_score ?? '-'} / 인플레: {clock?.inflation_score ?? '-'}
          </div>
          {clock?.asset_kr && (
            <div style={{ fontSize: '0.7rem', color: 'var(--text-secondary)', marginTop: '0.3rem',
              padding: '0.2rem 0.4rem', background: `${clock?.color || '#3b82f6'}12`, borderRadius: '4px' }}>
              {clock.asset_kr}
            </div>
          )}
        </div>

        {/* Yield Phase */}
        <div className="card" style={{ borderLeft: `3px solid ${YIELD_PHASE_COLORS[yieldPhase?.phase] || '#64748b'}`, textAlign: 'center' }}>
          <div className="card-label">Yield Curve Phase</div>
          <div className="card-value" style={{
            fontSize: '1.1rem',
            color: YIELD_PHASE_COLORS[yieldPhase?.phase] || 'var(--text-primary)',
          }}>
            {yieldPhase?.phase_kr || '-'}
            {yieldPhase?.risk_flag && <span style={{ marginLeft: '0.3rem' }}>{'⚠️'}</span>}
          </div>
          <div style={{ fontSize: '0.7rem', color: 'var(--text-muted)', marginTop: '0.25rem' }}>
            Spread: {yieldPhase?.current_spread ?? '-'}% / {yieldPhase?.trend || '-'}
          </div>
        </div>

        {/* Unified Risk Score */}
        <div className="card" style={{
          borderLeft: `3px solid ${RISK_LEVEL_COLORS[riskScore?.level] || '#64748b'}`,
          textAlign: 'center',
        }}>
          <div className="card-label">Macro Risk Score</div>
          <div className="card-value" style={{
            fontSize: '1.8rem',
            color: RISK_LEVEL_COLORS[riskScore?.level] || 'var(--text-primary)',
          }}>
            {riskScore?.score ?? '-'}
          </div>
          <div className="card-sub">{riskScore?.level_kr || '-'}</div>
          <div style={{ marginTop: '0.4rem', background: '#334155', borderRadius: '4px', height: '6px', overflow: 'hidden' }}>
            <div style={{
              width: `${Math.min(100, riskScore?.score || 0)}%`,
              height: '100%',
              borderRadius: '4px',
              background: RISK_LEVEL_COLORS[riskScore?.level] || '#64748b',
              transition: 'width 0.5s',
            }} />
          </div>
        </div>
      </div>

      {/* ── Phase K: Fear Gauge + Entry Scenarios ── */}
      {(fearGauge || entryScenarios) && (
        <div style={{ display: 'grid', gridTemplateColumns: '1fr 2fr', gap: '1rem', marginBottom: '1rem' }}>
          {/* Fear Gauge Card */}
          {fearGauge && (
            <div className="card" style={{ borderLeft: `3px solid ${FEAR_PHASE_COLORS[fearGauge.phase] || '#64748b'}`, textAlign: 'center' }}>
              <div className="card-label">Fear Gauge</div>
              <div style={{ fontSize: '2rem', lineHeight: 1.2 }}>
                {FEAR_PHASE_ICONS[fearGauge.phase] || '❓'}
              </div>
              <div className="card-value" style={{
                fontSize: '1.1rem',
                color: FEAR_PHASE_COLORS[fearGauge.phase] || 'var(--text-primary)',
              }}>
                {fearGauge.phase_kr || fearGauge.phase || '-'}
              </div>
              <div style={{ fontSize: '0.7rem', color: 'var(--text-muted)', marginTop: '0.25rem' }}>
                Conf: {((fearGauge.confidence ?? 0) * 100).toFixed(0)}%
              </div>
              {fearGauge.metrics && (
                <div style={{ fontSize: '0.7rem', color: 'var(--text-muted)', marginTop: '0.5rem',
                  display: 'flex', flexDirection: 'column', gap: '0.15rem', textAlign: 'left' }}>
                  <span>VIX: {fearGauge.metrics.vix_current?.toFixed(1) ?? '-'} (vel: {fearGauge.metrics.vix_velocity_5d?.toFixed(1) ?? '-'}%)</span>
                  <span>F&G: {fearGauge.metrics.fg_current ?? '-'} (mom: {fearGauge.metrics.fg_momentum_5d?.toFixed(1) ?? '-'})</span>
                  <span>P/C Spike: {fearGauge.metrics.put_call_spike ? 'Yes' : 'No'} / Backwd: {fearGauge.metrics.backwardation_streak ?? 0}d</span>
                </div>
              )}
              {fearGauge.action_kr && (
                <div style={{ fontSize: '0.7rem', color: 'var(--text-secondary)', marginTop: '0.5rem',
                  padding: '0.3rem 0.4rem', background: `${FEAR_PHASE_COLORS[fearGauge.phase] || '#64748b'}12`,
                  borderRadius: '4px', textAlign: 'left' }}>
                  {fearGauge.action_kr}
                </div>
              )}
            </div>
          )}

          {/* Entry Scenarios Table */}
          {entryScenarios && (
            <div className="card">
              <h3 style={{ fontSize: '0.85rem', marginBottom: '0.5rem' }}>Entry Scenarios (MA Reference)</h3>
              {entryScenarios.probability_bias && (
                <div style={{ fontSize: '0.7rem', color: 'var(--text-muted)', marginBottom: '0.5rem' }}>
                  Probability Bias: <strong style={{
                    color: entryScenarios.probability_bias === 'worst' ? '#ef4444'
                      : entryScenarios.probability_bias === 'best' ? '#22c55e' : '#eab308'
                  }}>{entryScenarios.probability_bias.toUpperCase()}</strong>
                </div>
              )}
              <table style={{ fontSize: '0.8rem' }}>
                <thead>
                  <tr>
                    <th>Scenario</th>
                    <th>KOSPI</th>
                    <th>SPY</th>
                    <th>USD/KRW</th>
                  </tr>
                </thead>
                <tbody>
                  {['best', 'base', 'worst'].map(s => {
                    const sc = entryScenarios.scenarios?.[s]
                    const scColor = s === 'best' ? '#22c55e' : s === 'worst' ? '#ef4444' : '#eab308'
                    return (
                      <tr key={s}>
                        <td style={{ fontWeight: 600, color: scColor }}>
                          {s === 'best' ? 'Best (MA20)' : s === 'base' ? 'Base (MA60)' : 'Worst (MA120)'}
                        </td>
                        <td>{sc?.kospi ? `${sc.kospi.toFixed(0)}` : '-'}</td>
                        <td>{sc?.spy ? `$${sc.spy.toFixed(1)}` : '-'}</td>
                        <td>{sc?.usd_krw ? `${sc.usd_krw.toFixed(0)}` : '-'}</td>
                      </tr>
                    )
                  })}
                </tbody>
              </table>
              {/* Benchmark MA details */}
              {entryScenarios.benchmarks && (
                <div style={{ marginTop: '0.5rem', display: 'flex', gap: '1rem', flexWrap: 'wrap' }}>
                  {Object.entries(entryScenarios.benchmarks).map(([name, b]) => (
                    <div key={name} style={{ fontSize: '0.65rem', color: 'var(--text-muted)' }}>
                      <strong>{name}</strong>: MA20={b.ma20?.toFixed(1) ?? '-'} / MA60={b.ma60?.toFixed(1) ?? '-'} / MA120={b.ma120?.toFixed(1) ?? '-'}
                    </div>
                  ))}
                </div>
              )}
            </div>
          )}
        </div>
      )}

      {/* Sector-Macro Impact */}
      {sectorImpact?.sectors?.length > 0 && (
        <div className="table-container" style={{ marginBottom: '1rem' }}>
          <div className="table-header">
            <h3>Sector-Macro Cross Impact</h3>
          </div>
          <table style={{ fontSize: '0.8rem' }}>
            <thead>
              <tr>
                <th>Sector</th>
                <th>Adjustment</th>
                <th>Oil</th>
                <th>Rate</th>
                <th>FX</th>
                <th>DXY</th>
                <th>Warnings</th>
              </tr>
            </thead>
            <tbody>
              {sectorImpact.sectors.filter(s => s.adjustment_score !== 0).slice(0, 12).map((s, i) => (
                <tr key={i}>
                  <td style={{ fontWeight: 600 }}>{s.sector}</td>
                  <td style={{
                    fontWeight: 700,
                    color: s.adjustment_score > 0 ? 'var(--green)' : s.adjustment_score < 0 ? 'var(--red)' : 'var(--text-muted)',
                  }}>
                    {s.adjustment_score > 0 ? '+' : ''}{s.adjustment_score.toFixed(1)}
                  </td>
                  <td style={{ color: (s.factors?.oil?.contribution || 0) > 0 ? 'var(--green)' : (s.factors?.oil?.contribution || 0) < 0 ? 'var(--red)' : 'var(--text-muted)' }}>
                    {(s.factors?.oil?.contribution || 0).toFixed(1)}
                  </td>
                  <td style={{ color: (s.factors?.rate?.contribution || 0) > 0 ? 'var(--green)' : (s.factors?.rate?.contribution || 0) < 0 ? 'var(--red)' : 'var(--text-muted)' }}>
                    {(s.factors?.rate?.contribution || 0).toFixed(1)}
                  </td>
                  <td style={{ color: (s.factors?.fx?.contribution || 0) > 0 ? 'var(--green)' : (s.factors?.fx?.contribution || 0) < 0 ? 'var(--red)' : 'var(--text-muted)' }}>
                    {(s.factors?.fx?.contribution || 0).toFixed(1)}
                  </td>
                  <td style={{ color: (s.factors?.dxy?.contribution || 0) > 0 ? 'var(--green)' : (s.factors?.dxy?.contribution || 0) < 0 ? 'var(--red)' : 'var(--text-muted)' }}>
                    {(s.factors?.dxy?.contribution || 0).toFixed(1)}
                  </td>
                  <td style={{ fontSize: '0.7rem', color: 'var(--text-muted)', maxWidth: '200px' }}>
                    {(s.warnings || []).join('; ') || '-'}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      {/* ── Phase K: Capitulation Scan + Crisis Hedge ── */}
      {(capitulation?.candidates?.length > 0 || crisisHedge?.hedge_candidates?.length > 0) && (
        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '1rem', marginBottom: '1rem' }}>
          {/* Capitulation Scan */}
          {capitulation?.candidates?.length > 0 && (
            <div className="card" style={{ borderLeft: '3px solid #ef4444' }}>
              <h3 style={{ fontSize: '0.85rem', marginBottom: '0.5rem', color: '#ef4444' }}>
                {'💥'} Capitulation Detected ({capitulation.count})
              </h3>
              <div style={{ fontSize: '0.7rem', color: 'var(--text-muted)', marginBottom: '0.5rem' }}>
                Volume spike + price drop = panic selling candidates
              </div>
              <table style={{ fontSize: '0.8rem' }}>
                <thead>
                  <tr>
                    <th>Symbol</th>
                    <th>Volume Ratio</th>
                    <th>Price Chg</th>
                    <th>Date</th>
                  </tr>
                </thead>
                <tbody>
                  {capitulation.candidates.slice(0, 8).map((c, i) => (
                    <tr key={i}>
                      <td style={{ fontWeight: 600 }}>{c.symbol}</td>
                      <td>{c.trigger_value ? `${Number(c.trigger_value).toFixed(1)}x` : '-'}</td>
                      <td style={{ color: 'var(--red)' }}>
                        {c.trigger_description?.match(/-[\d.]+%/)?.[0] || '-'}
                      </td>
                      <td style={{ fontSize: '0.7rem' }}>{c.detected_date?.slice(5) || '-'}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}

          {/* Crisis Hedge Candidates */}
          {crisisHedge?.hedge_candidates?.length > 0 && (
            <div className="card" style={{ borderLeft: '3px solid #3b82f6' }}>
              <h3 style={{ fontSize: '0.85rem', marginBottom: '0.5rem', color: '#3b82f6' }}>
                {'🛡️'} Crisis Hedge Candidates
              </h3>
              <div style={{ fontSize: '0.7rem', color: 'var(--text-muted)', marginBottom: '0.5rem' }}>
                Defense sectors with RS {'>'} 1.0 during {crisisHedge.risk_regime || 'risk-off'}
              </div>
              <table style={{ fontSize: '0.8rem' }}>
                <thead>
                  <tr>
                    <th>Symbol</th>
                    <th>Sector</th>
                    <th>RS</th>
                    <th>Return</th>
                  </tr>
                </thead>
                <tbody>
                  {crisisHedge.hedge_candidates.slice(0, 8).map((h, i) => (
                    <tr key={i}>
                      <td style={{ fontWeight: 600 }}>{h.symbol}</td>
                      <td style={{ fontSize: '0.7rem' }}>{h.sector}</td>
                      <td style={{ color: h.rs > 1 ? 'var(--green)' : 'var(--text-muted)', fontWeight: 600 }}>
                        {h.rs?.toFixed(3) || '-'}
                      </td>
                      <td style={{ color: (h.return_pct || 0) >= 0 ? 'var(--green)' : 'var(--red)' }}>
                        {h.return_pct != null ? `${h.return_pct >= 0 ? '+' : ''}${h.return_pct.toFixed(1)}%` : '-'}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      )}

      {/* Investment Clock Detail + Season Axes */}
      {(clock || season) && (
        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '1rem', marginBottom: '1rem' }}>
          {/* Investment Clock Quadrant Visualization */}
          {clock && (
            <div className="card">
              <h3 style={{ fontSize: '0.85rem', marginBottom: '0.75rem' }}>Investment Clock</h3>
              <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '2px', maxWidth: '280px', margin: '0 auto' }}>
                {[
                  { key: 'recovery', label: 'Recovery', kr: '회복', pos: 'growth↑ inflation↓', color: '#22c55e' },
                  { key: 'overheat', label: 'Overheat', kr: '과열', pos: 'growth↑ inflation↑', color: '#f59e0b' },
                  { key: 'reflation', label: 'Reflation', kr: '환기', pos: 'growth↓ inflation↓', color: '#3b82f6' },
                  { key: 'stagflation', label: 'Stagflation', kr: '침체', pos: 'growth↓ inflation↑', color: '#ef4444' },
                ].map(q => {
                  const isActive = clock.quadrant?.toLowerCase() === q.key
                  return (
                    <div key={q.key} style={{
                      padding: '0.75rem 0.5rem',
                      background: isActive ? `${q.color}20` : '#1e293b',
                      border: isActive ? `2px solid ${q.color}` : '1px solid #334155',
                      borderRadius: '6px',
                      textAlign: 'center',
                    }}>
                      <div style={{ fontWeight: 700, fontSize: '0.85rem', color: isActive ? q.color : 'var(--text-muted)' }}>
                        {q.kr}
                      </div>
                      <div style={{ fontSize: '0.65rem', color: 'var(--text-muted)' }}>{q.pos}</div>
                    </div>
                  )
                })}
              </div>
              {clock.description_kr && (
                <div style={{ fontSize: '0.75rem', color: 'var(--text-secondary)', marginTop: '0.75rem', textAlign: 'center' }}>
                  {clock.description_kr}
                </div>
              )}
            </div>
          )}

          {/* Season Axes Breakdown */}
          {season && season.axes && (
            <div className="card">
              <h3 style={{ fontSize: '0.85rem', marginBottom: '0.75rem' }}>Season Axes</h3>
              <div style={{ display: 'flex', flexDirection: 'column', gap: '0.75rem' }}>
                {/* Rate Axis */}
                <div>
                  <div style={{ fontSize: '0.75rem', color: 'var(--text-muted)', marginBottom: '0.25rem' }}>
                    Rate Direction: <strong style={{ color: season.axes?.rate_direction === 'falling' ? '#22c55e' : season.axes?.rate_direction === 'rising' ? '#ef4444' : '#eab308' }}>
                      {season.axes?.rate_direction || '-'}
                    </strong>
                    <span style={{ marginLeft: '0.5rem' }}>({((season.axes?.rate_momentum ?? 0) * 100).toFixed(1)}%)</span>
                  </div>
                  <div style={{ background: '#334155', borderRadius: '4px', height: '6px', overflow: 'hidden' }}>
                    <div style={{
                      width: `${Math.min(100, Math.abs(season.axes?.rate_momentum ?? 0) * 500)}%`,
                      height: '100%',
                      borderRadius: '4px',
                      background: season.axes?.rate_direction === 'falling' ? '#22c55e' : season.axes?.rate_direction === 'rising' ? '#ef4444' : '#eab308',
                    }} />
                  </div>
                </div>
                {/* Growth Proxy */}
                <div>
                  <div style={{ fontSize: '0.75rem', color: 'var(--text-muted)', marginBottom: '0.25rem' }}>
                    Growth Proxy: <strong style={{ color: season.axes?.growth_direction === 'improving' ? '#22c55e' : season.axes?.growth_direction === 'deteriorating' ? '#ef4444' : '#eab308' }}>
                      {season.axes?.growth_direction || '-'}
                    </strong>
                    <span style={{ marginLeft: '0.5rem' }}>({((season.axes?.growth_proxy ?? 0) * 100).toFixed(1)}%)</span>
                  </div>
                  <div style={{ background: '#334155', borderRadius: '4px', height: '6px', overflow: 'hidden' }}>
                    <div style={{
                      width: `${Math.min(100, Math.abs(season.axes?.growth_proxy ?? 0) * 500)}%`,
                      height: '100%',
                      borderRadius: '4px',
                      background: season.axes?.growth_direction === 'improving' ? '#22c55e' : season.axes?.growth_direction === 'deteriorating' ? '#ef4444' : '#eab308',
                    }} />
                  </div>
                </div>
                {/* Component breakdown */}
                {season.axes?.components && (
                  <div style={{ fontSize: '0.7rem', color: 'var(--text-muted)', display: 'flex', gap: '0.5rem', flexWrap: 'wrap' }}>
                    <span>Copper: {((season.axes.components?.copper_momentum ?? 0) * 100).toFixed(1)}%</span>
                    <span>ETF: {((season.axes.components?.etf_momentum ?? 0) * 100).toFixed(1)}%</span>
                    <span>KR Flow: {((season.axes.components?.kr_flow_momentum ?? 0) * 100).toFixed(1)}%</span>
                  </div>
                )}
              </div>
              {season.description_kr && (
                <div style={{ fontSize: '0.75rem', color: 'var(--text-secondary)', marginTop: '0.75rem',
                  padding: '0.4rem', background: 'rgba(245,158,11,0.06)', borderRadius: '4px' }}>
                  {season.description_kr}
                </div>
              )}
            </div>
          )}
        </div>
      )}

      {/* Market Season Cycle Guide */}
      <div className="card" style={{ marginBottom: '1rem' }}>
        <h3 style={{ fontSize: '0.85rem', marginBottom: '0.75rem' }}>{'🔄'} 시장 사이클 가이드 (우라가미 쿠니오)</h3>
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: '0.5rem' }}>
          {[
            { key: 'spring', icon: '🌱', kr: '금융장세', en: 'Spring', desc: '금리 하락 + 경기 회복 초기\n유동성 확대로 주식 강세 시작', strategy: '주식 비중 확대, 성장주 중심', color: '#22c55e', axes: '금리↓ 성장↑' },
            { key: 'summer', icon: '☀️', kr: '실적장세', en: 'Summer', desc: '금리 상승 시작이나 실적 개선이 더 강함\n실적 우량주 강세', strategy: '실적 우량주 선별, 섹터 로테이션', color: '#f59e0b', axes: '금리↑ 성장↑' },
            { key: 'autumn', icon: '🍂', kr: '역금융장세', en: 'Autumn', desc: '금리 고점/상승 지속 + 성장 둔화\n밸류에이션 부담 증가', strategy: '비중 축소, 방어주 전환, 현금 확대', color: '#ef4444', axes: '금리↑ 성장↓' },
            { key: 'winter', icon: '❄️', kr: '역실적장세', en: 'Winter', desc: '금리 하락 시작이나 실적 악화 지속\n본격적 하락장', strategy: '현금/채권 극대화, 역발상 매수 준비', color: '#3b82f6', axes: '금리↓ 성장↓' },
          ].map(s => {
            const isCurrent = season?.season?.toLowerCase() === s.key
            return (
              <div key={s.key} style={{
                padding: '0.75rem', borderRadius: '8px', position: 'relative',
                background: isCurrent ? `${s.color}15` : '#1e293b',
                border: isCurrent ? `2px solid ${s.color}` : '1px solid #334155',
              }}>
                {isCurrent && (
                  <div style={{ position: 'absolute', top: '-8px', right: '8px', fontSize: '0.6rem', fontWeight: 700,
                    color: s.color, background: 'var(--bg-secondary)', padding: '0 4px', borderRadius: '4px' }}>
                    현재
                  </div>
                )}
                <div style={{ textAlign: 'center', marginBottom: '0.3rem' }}>
                  <span style={{ fontSize: '1.5rem' }}>{s.icon}</span>
                </div>
                <div style={{ textAlign: 'center', fontWeight: 700, fontSize: '0.9rem', color: isCurrent ? s.color : 'var(--text-primary)' }}>
                  {s.kr}
                </div>
                <div style={{ textAlign: 'center', fontSize: '0.65rem', color: 'var(--text-muted)', marginBottom: '0.4rem' }}>
                  {s.en} · {s.axes}
                </div>
                <div style={{ fontSize: '0.7rem', color: 'var(--text-secondary)', lineHeight: 1.5, whiteSpace: 'pre-line', marginBottom: '0.4rem' }}>
                  {s.desc}
                </div>
                <div style={{ fontSize: '0.65rem', color: s.color, padding: '0.2rem 0.3rem', background: `${s.color}08`, borderRadius: '4px' }}>
                  전략: {s.strategy}
                </div>
              </div>
            )
          })}
        </div>
        <div style={{ textAlign: 'center', marginTop: '0.5rem', fontSize: '0.7rem', color: 'var(--text-muted)' }}>
          봄 → 여름 → 가을 → 겨울 → 봄 (순환) · 우라가미 쿠니오(浦上邦雄) 모델 기반
        </div>
      </div>

      {/* Summary Cards */}
      <div className="card-grid" style={{ gridTemplateColumns: 'repeat(3, 1fr)' }}>
        {/* Regime Card */}
        <div className="card" style={{ borderLeft: `3px solid ${REGIME_COLORS[risk.regime] || '#64748b'}` }}>
          <div className="card-label">Market Regime</div>
          <div className="card-value" style={{ color: REGIME_COLORS[risk.regime] || 'var(--text-primary)', fontSize: '1.3rem' }}>
            {risk.regime_kr || '-'}
          </div>
          <div className="card-sub">{driver.driver_kr || '-'}</div>
          <div style={{ fontSize: '0.7rem', color: 'var(--text-muted)', marginTop: '0.25rem' }}>
            Risk Score: {risk.score ?? '-'} / Confidence: {driver.confidence ?? '-'}
          </div>
        </div>

        {/* Stagflation Gauge */}
        <div className="card" style={{ borderLeft: `3px solid ${STAG_COLORS[stag.level] || '#64748b'}` }}>
          <div className="card-label">Stagflation Risk</div>
          <div className="card-value" style={{ color: STAG_COLORS[stag.level] || 'var(--text-primary)', fontSize: '1.3rem' }}>
            {stag.index ?? '-'}
          </div>
          <div className="card-sub">{stag.level_kr || '-'}</div>
          {/* Progress bar */}
          <div style={{ marginTop: '0.5rem', background: '#334155', borderRadius: '4px', height: '8px', overflow: 'hidden' }}>
            <div style={{
              width: `${Math.min(100, stag.index || 0)}%`,
              height: '100%',
              borderRadius: '4px',
              background: stag.index > 70 ? '#ef4444' : stag.index > 50 ? '#f97316' : stag.index > 30 ? '#eab308' : '#22c55e',
              transition: 'width 0.5s',
            }} />
          </div>
        </div>

        {/* Cross-Market Recommendation */}
        <div className="card" style={{ borderLeft: `3px solid ${REC_COLORS[cm.recommendation] || '#64748b'}` }}>
          <div className="card-label">Cross-Market</div>
          <div className="card-value" style={{ color: REC_COLORS[cm.recommendation] || 'var(--text-primary)', fontSize: '1.3rem' }}>
            {cm.recommendation_kr || '-'}
          </div>
          <div className="card-sub">KR {cm.kr_score ?? '-'} / US {cm.us_score ?? '-'}</div>
        </div>
      </div>

      {/* Cross-Market Radar + Stagflation Breakdown */}
      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '1rem', marginBottom: '1rem' }}>
        {/* Radar Chart */}
        <div className="card">
          <h3 style={{ fontSize: '0.85rem', marginBottom: '0.5rem' }}>KR vs US Factor Comparison</h3>
          {radarData.length > 0 ? (
            <ResponsiveContainer width="100%" height={260}>
              <RadarChart data={radarData}>
                <PolarGrid stroke="#334155" />
                <PolarAngleAxis dataKey="factor" tick={{ fill: '#94a3b8', fontSize: 11 }} />
                <PolarRadiusAxis angle={90} domain={[0, 100]} tick={{ fill: '#64748b', fontSize: 9 }} />
                <Radar name="KR" dataKey="KR" stroke="#3b82f6" fill="#3b82f6" fillOpacity={0.2} />
                <Radar name="US" dataKey="US" stroke="#a855f7" fill="#a855f7" fillOpacity={0.2} />
                <Legend wrapperStyle={{ fontSize: '0.75rem' }} />
                <Tooltip contentStyle={{ background: '#1e293b', border: '1px solid #334155', fontSize: '0.8rem' }} />
              </RadarChart>
            </ResponsiveContainer>
          ) : <div style={{ padding: '2rem', textAlign: 'center', color: 'var(--text-muted)' }}>No data</div>}
        </div>

        {/* Stagflation Breakdown */}
        <div className="card">
          <h3 style={{ fontSize: '0.85rem', marginBottom: '0.5rem' }}>Stagflation Components</h3>
          {stagBars.length > 0 ? (
            <ResponsiveContainer width="100%" height={260}>
              <BarChart data={stagBars} layout="vertical" margin={{ left: 10, right: 20 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="#334155" />
                <XAxis type="number" domain={[0, 100]} tick={{ fill: '#94a3b8', fontSize: 10 }} />
                <YAxis type="category" dataKey="name" tick={{ fill: '#94a3b8', fontSize: 10 }} width={80} />
                <Tooltip contentStyle={{ background: '#1e293b', border: '1px solid #334155', fontSize: '0.8rem' }}
                  formatter={(v) => [`${v.toFixed(1)}`, 'Score']} />
                <Bar dataKey="score" radius={[0, 4, 4, 0]} barSize={16}>
                  {stagBars.map((d, i) => (
                    <Cell key={i} fill={d.score > 60 ? '#ef4444' : d.score > 35 ? '#eab308' : '#22c55e'} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          ) : <div style={{ padding: '2rem', textAlign: 'center', color: 'var(--text-muted)' }}>No data</div>}
        </div>
      </div>

      {/* Cross-Market Factor Detail */}
      {cm.factors && (
        <div className="table-container" style={{ marginBottom: '1rem' }}>
          <div className="table-header">
            <h3>Factor Breakdown</h3>
          </div>
          <table>
            <thead>
              <tr>
                <th>Factor</th>
                <th>Analysis</th>
                <th>KR Impact</th>
                <th>US Impact</th>
              </tr>
            </thead>
            <tbody>
              {Object.entries(cm.factors).map(([key, f]) => (
                <tr key={key}>
                  <td style={{ fontWeight: 600 }}>
                    {key === 'fx_trend' ? 'FX (USD/KRW)' : key === 'volatility' ? 'Volatility (VIX)' : key === 'yield_env' ? 'Yield Env' : key === 'fund_flow' ? 'Fund Flow' : 'Signal Momentum'}
                  </td>
                  <td style={{ fontSize: '0.8rem', color: 'var(--text-secondary)' }}>{f.label}</td>
                  <td style={{ color: f.kr_impact >= 0 ? 'var(--green)' : 'var(--red)', fontWeight: 600 }}>
                    {f.kr_impact >= 0 ? '+' : ''}{f.kr_impact?.toFixed(2)}
                  </td>
                  <td style={{ color: f.us_impact >= 0 ? 'var(--green)' : 'var(--red)', fontWeight: 600 }}>
                    {f.us_impact >= 0 ? '+' : ''}{f.us_impact?.toFixed(2)}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      {/* Macro Trends Chart */}
      <div className="card" style={{ marginBottom: '1rem' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '0.5rem' }}>
          <h3 style={{ fontSize: '0.85rem' }}>Macro Trends</h3>
          <div style={{ display: 'flex', gap: '0.3rem' }}>
            {[7, 30, 90].map(d => (
              <button key={d} className={`btn btn-sm ${trendDays === d ? 'btn-primary' : 'btn-outline'}`}
                onClick={() => setTrendDays(d)} style={{ fontSize: '0.7rem', padding: '0.2rem 0.5rem' }}>
                {d}d
              </button>
            ))}
          </div>
        </div>
        {trends.length > 0 ? (
          <ResponsiveContainer width="100%" height={280}>
            <LineChart data={trends} margin={{ left: 5, right: 5 }}>
              <CartesianGrid strokeDasharray="3 3" stroke="#334155" />
              <XAxis dataKey="date" tick={{ fill: '#94a3b8', fontSize: 9 }}
                tickFormatter={v => v?.slice(5)} />
              <YAxis yAxisId="left" tick={{ fill: '#94a3b8', fontSize: 9 }}
                domain={['auto', 'auto']} />
              <YAxis yAxisId="right" orientation="right" tick={{ fill: '#94a3b8', fontSize: 9 }}
                domain={['auto', 'auto']} />
              <Tooltip contentStyle={{ background: '#1e293b', border: '1px solid #334155', fontSize: '0.75rem' }} />
              <Legend wrapperStyle={{ fontSize: '0.7rem' }} />
              <Line yAxisId="left" type="monotone" dataKey="vix" stroke="#ef4444" name="VIX" dot={false} strokeWidth={2} />
              <Line yAxisId="left" type="monotone" dataKey="fear_greed" stroke="#eab308" name="F&G" dot={false} strokeWidth={1.5} />
              <Line yAxisId="left" type="monotone" dataKey="yield_spread" stroke="#22c55e" name="Yield Spread" dot={false} strokeWidth={1.5} />
              <Line yAxisId="right" type="monotone" dataKey="usd_krw" stroke="#3b82f6" name="USD/KRW" dot={false} strokeWidth={1.5} />
              <Line yAxisId="right" type="monotone" dataKey="dxy" stroke="#a855f7" name="DXY" dot={false} strokeWidth={1.5} />
            </LineChart>
          </ResponsiveContainer>
        ) : <div style={{ padding: '2rem', textAlign: 'center', color: 'var(--text-muted)' }}>No trend data</div>}
      </div>

      {/* Action Items */}
      {cm.action_items && cm.action_items.length > 0 && (
        <div className="card" style={{ borderLeft: '3px solid var(--accent)' }}>
          <h3 style={{ fontSize: '0.85rem', marginBottom: '0.5rem' }}>{'💡'} Action Items</h3>
          <ul style={{ listStyle: 'none', padding: 0, display: 'flex', flexDirection: 'column', gap: '0.4rem' }}>
            {cm.action_items.map((item, i) => (
              <li key={i} style={{ fontSize: '0.8rem', color: 'var(--text-secondary)', padding: '0.4rem 0.6rem', background: 'rgba(59,130,246,0.06)', borderRadius: '0.25rem' }}>
                {'•'} {item}
              </li>
            ))}
          </ul>
        </div>
      )}
    </div>
  )
}

import { useState, useEffect, useMemo, useCallback } from 'react'
import { useToast } from '../components/Toast'
import { getSoxlDashboard, getSoxlLevels, getSoxlOptimizeHistory, getSoxlAlerts } from '../api'
import {
  LineChart, Line, AreaChart, Area, BarChart, Bar,
  ComposedChart, XAxis, YAxis, Tooltip, ResponsiveContainer,
  CartesianGrid, ReferenceLine, ReferenceArea, Legend, Brush,
  Cell,
} from 'recharts'

/* ── Constants ── */
const SIGNAL_COLORS = {
  BUY: 'var(--green)', SELL: 'var(--red)', HOLD: 'var(--yellow)',
  STRONG_BUY: '#00e676', STRONG_SELL: '#ff1744',
}
const STANCE_EMOJI = {
  STRONG_BUY: '🟢', BUY: '🟢', SELL: '🔴',
  STRONG_SELL: '🔴', HOLD: '🟡',
}
const PERIOD_OPTIONS = [
  { value: 30, label: '1M' },
  { value: 60, label: '2M' },
  { value: 90, label: '3M' },
  { value: 180, label: '6M' },
  { value: 365, label: '1Y' },
]

export default function Soxl({ onNavigate, refreshKey }) {
  const [data, setData] = useState(null)
  const [levels, setLevels] = useState(null)
  const [loading, setLoading] = useState(true)
  const [activeTab, setActiveTab] = useState('overview')
  const [days, setDays] = useState(90)
  const [latestOpt, setLatestOpt] = useState(null)
  const [activeAlertCount, setActiveAlertCount] = useState(0)
  const toast = useToast()

  const fetchData = useCallback((d) => {
    setLoading(true)
    Promise.all([
      getSoxlDashboard(d),
      getSoxlLevels(),
      getSoxlOptimizeHistory({ limit: 1 }).catch(() => ({ results: [] })),
      getSoxlAlerts().catch(() => ({ alerts: [] })),
    ])
      .then(([dd, l, opt, alt]) => {
        setData(dd)
        setLevels(l)
        setLatestOpt(opt?.results?.[0] || null)
        setActiveAlertCount((alt?.alerts || []).filter(a => a.active).length)
      })
      .catch(err => toast.error('SOXL 데이터 로드 실패: ' + err.message))
      .finally(() => setLoading(false))
  }, [toast])

  useEffect(() => { fetchData(days) }, [refreshKey, days])

  if (loading) return <LoadingSkeleton />
  if (!data) return (
    <div className="card" style={{ textAlign: 'center', padding: '3rem' }}>
      <div style={{ fontSize: '3rem', marginBottom: '1rem' }}>📊</div>
      <h3>SOXL 데이터가 없습니다</h3>
      <p style={{ color: 'var(--text-muted)', margin: '0.5rem 0 1rem' }}>
        Watchlist에 SOXL을 추가하고 파이프라인을 실행해주세요.
      </p>
      <button className="btn btn-primary" onClick={() => onNavigate('data-admin')}>
        📋 데이터 관리 →
      </button>
    </div>
  )

  const { prices, technicals, signals, performance, strategy } = data
  const tabs = [
    { id: 'overview', label: '오버뷰', icon: '📊' },
    { id: 'charts', label: '차트 분석', icon: '📈' },
    { id: 'strategy', label: '매매 전략', icon: '🎯' },
    { id: 'signals', label: '시그널 이력', icon: '⚡' },
  ]

  return (
    <div>
      {/* Header */}
      <div className="page-header" style={{ marginBottom: '0.75rem' }}>
        <div>
          <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem' }}>
            <h2 style={{ margin: 0 }}>💹 SOXL</h2>
            {performance?.current_price && (
              <span style={{ fontSize: '1.1rem', fontWeight: 700, color: 'var(--text-primary)' }}>
                ${performance.current_price.toFixed(2)}
              </span>
            )}
            {performance?.change_1d != null && (
              <span style={{
                fontSize: '0.85rem', fontWeight: 600,
                color: performance.change_1d >= 0 ? 'var(--green)' : 'var(--red)',
              }}>
                {performance.change_1d >= 0 ? '▲' : '▼'} {fmtPct(performance.change_1d)}
              </span>
            )}
            {strategy && (
              <StanceBadge stance={strategy.stance} />
            )}
          </div>
          <p style={{ color: 'var(--text-muted)', margin: '0.25rem 0 0', fontSize: '0.75rem' }}>
            Direxion Daily Semiconductor Bull 3X &mdash; {data.asset_type}
            {data.updated_at && (
              <span style={{ marginLeft: '0.75rem', opacity: 0.7 }}>
                {new Date(data.updated_at).toLocaleTimeString('ko-KR', { hour: '2-digit', minute: '2-digit' })} 업데이트
              </span>
            )}
          </p>
        </div>
        <div style={{ display: 'flex', gap: '0.5rem', alignItems: 'center' }}>
          {/* Period Selector */}
          <div style={{ display: 'flex', gap: '0.15rem', background: 'var(--bg-secondary)', borderRadius: '0.5rem', padding: '0.15rem' }}>
            {PERIOD_OPTIONS.map(p => (
              <button key={p.value}
                className={`btn ${days === p.value ? 'btn-primary' : ''}`}
                style={{ padding: '0.25rem 0.5rem', fontSize: '0.7rem', minWidth: '2rem' }}
                onClick={() => setDays(p.value)}>
                {p.label}
              </button>
            ))}
          </div>
          <button className="btn btn-primary" onClick={() => onNavigate('soxl-live')}
            style={{ fontSize: '0.8rem', padding: '0.4rem 0.75rem' }}>
            ⚡ 실시간 →
          </button>
          <button className="btn btn-primary" onClick={() => onNavigate('geopolitical')}
            style={{ fontSize: '0.8rem', padding: '0.4rem 0.75rem' }}>
            🌍 이란 이슈 →
          </button>
        </div>
      </div>

      {/* Quick KPI Strip */}
      <QuickKpiStrip performance={performance} technicals={technicals} />

      {/* Latest Optimization + Active Alerts Strip */}
      <div style={{ display: 'flex', gap: '0.5rem', marginBottom: '0.75rem', flexWrap: 'wrap' }}>
        {/* Latest Optimize Params Card */}
        <div className="card" style={{
          flex: '1 1 300px', padding: '0.6rem 0.85rem',
          display: 'flex', alignItems: 'center', gap: '0.75rem',
          background: 'var(--bg-secondary)', borderRadius: '0.5rem',
        }}>
          <span style={{ fontSize: '1.1rem' }}>🎯</span>
          {latestOpt ? (
            <div style={{ flex: 1 }}>
              <div style={{ fontSize: '0.65rem', color: 'var(--text-muted)', marginBottom: '0.15rem' }}>
                최근 최적화 — 모드 {latestOpt.mode}
                <span style={{ marginLeft: 6, opacity: 0.6 }}>
                  {latestOpt.run_at ? new Date(latestOpt.run_at).toLocaleDateString('ko-KR') : ''}
                </span>
              </div>
              <div style={{ display: 'flex', gap: '0.75rem', fontSize: '0.75rem', flexWrap: 'wrap' }}>
                <span>Sharpe <b style={{ color: (latestOpt.sharpe || 0) > 0 ? '#22c55e' : '#ef4444' }}>{latestOpt.sharpe?.toFixed(2) ?? '—'}</b></span>
                {latestOpt.params?.rsi_entry != null && <span>RSI진입 <b>{latestOpt.params.rsi_entry}</b></span>}
                {latestOpt.params?.stop_loss_pct != null && <span>손절 <b>{latestOpt.params.stop_loss_pct}%</b></span>}
                {latestOpt.params?.take_profit_pct != null && <span>익절 <b>{latestOpt.params.take_profit_pct}%</b></span>}
              </div>
            </div>
          ) : (
            <span style={{ fontSize: '0.7rem', color: 'var(--text-muted)' }}>
              최적화 실행 필요 — 실시간 페이지에서 실행
            </span>
          )}
        </div>

        {/* Active Alerts Badge */}
        <div className="card" style={{
          flex: '0 0 auto', padding: '0.6rem 0.85rem',
          display: 'flex', alignItems: 'center', gap: '0.5rem',
          background: 'var(--bg-secondary)', borderRadius: '0.5rem',
          cursor: 'pointer',
        }}
          onClick={() => onNavigate('soxl-live')}>
          <span style={{ fontSize: '1.1rem' }}>⚡</span>
          <div>
            <div style={{ fontSize: '0.65rem', color: 'var(--text-muted)' }}>활성 알림</div>
            <div style={{ fontSize: '0.85rem', fontWeight: 700, color: activeAlertCount > 0 ? '#f59e0b' : 'var(--text-muted)' }}>
              {activeAlertCount > 0 ? `${activeAlertCount}건` : '없음'}
            </div>
          </div>
        </div>
      </div>

      {/* Tabs */}
      <div style={{
        display: 'flex', gap: '0.25rem', marginBottom: '1rem',
        borderBottom: '2px solid var(--border)', paddingBottom: '0',
      }}>
        {tabs.map(t => (
          <button key={t.id}
            onClick={() => setActiveTab(t.id)}
            style={{
              padding: '0.5rem 1rem', fontSize: '0.8rem', fontWeight: 600,
              background: 'none', border: 'none', cursor: 'pointer',
              color: activeTab === t.id ? 'var(--accent)' : 'var(--text-muted)',
              borderBottom: activeTab === t.id ? '2px solid var(--accent)' : '2px solid transparent',
              marginBottom: '-2px', transition: 'all 0.15s',
            }}>
            {t.icon} {t.label}
          </button>
        ))}
      </div>

      {activeTab === 'overview' && <OverviewTab data={data} levels={levels} onNavigate={onNavigate} signals={signals} />}
      {activeTab === 'charts' && <ChartsTab technicals={technicals} prices={prices} levels={levels} signals={signals} />}
      {activeTab === 'strategy' && <StrategyTab strategy={strategy} performance={performance} activeAlertCount={activeAlertCount} onNavigate={onNavigate} />}
      {activeTab === 'signals' && <SignalsTab signals={signals} />}
    </div>
  )
}

/* ── Loading Skeleton ── */
function LoadingSkeleton() {
  const shimmer = {
    background: 'linear-gradient(90deg, var(--bg-secondary) 25%, var(--border) 50%, var(--bg-secondary) 75%)',
    backgroundSize: '200% 100%',
    animation: 'shimmer 1.5s infinite',
    borderRadius: '0.5rem',
  }
  return (
    <div>
      <style>{`@keyframes shimmer { 0% { background-position: 200% 0; } 100% { background-position: -200% 0; } }`}</style>
      <div style={{ ...shimmer, height: '2rem', width: '200px', marginBottom: '1rem' }} />
      <div className="card-grid" style={{ gridTemplateColumns: 'repeat(auto-fit, minmax(120px, 1fr))', marginBottom: '1rem' }}>
        {[...Array(8)].map((_, i) => <div key={i} style={{ ...shimmer, height: '4rem' }} />)}
      </div>
      <div style={{ ...shimmer, height: '350px', marginBottom: '1rem' }} />
      <div style={{ ...shimmer, height: '200px' }} />
    </div>
  )
}

/* ── Stance Badge ── */
function StanceBadge({ stance }) {
  const bg = stance.includes('BUY') ? 'rgba(0,230,118,0.15)' :
    stance.includes('SELL') ? 'rgba(255,23,68,0.15)' : 'rgba(255,235,59,0.15)'
  const color = stance.includes('BUY') ? '#00e676' :
    stance.includes('SELL') ? '#ff1744' : '#ffeb3b'
  return (
    <span style={{
      padding: '0.25rem 0.75rem', borderRadius: '2rem', fontWeight: 700,
      fontSize: '0.75rem', background: bg, color,
    }}>
      {STANCE_EMOJI[stance] || '⭐'} {stance}
    </span>
  )
}

/* ── Quick KPI Strip (always visible) ── */
function QuickKpiStrip({ performance, technicals }) {
  const p = performance || {}
  const items = [
    { label: '현재가', value: p.current_price ? `$${p.current_price.toFixed(2)}` : '-', color: 'var(--text-primary)' },
    { label: '1일', value: fmtPct(p.change_1d), color: pctColor(p.change_1d) },
    { label: '5일', value: fmtPct(p.change_5d), color: pctColor(p.change_5d) },
    { label: '20일', value: fmtPct(p.change_20d), color: pctColor(p.change_20d) },
    { label: 'RSI', value: technicals?.rsi_14?.toFixed(1) || '-', color: rsiColor(technicals?.rsi_14) },
    { label: '변동성', value: p.volatility_20d_ann ? `${p.volatility_20d_ann}%` : '-', color: p.volatility_20d_ann > 80 ? 'var(--red)' : 'var(--yellow)' },
    { label: '거래량', value: fmtVolume(p.latest_volume), color: 'var(--text-primary)' },
    { label: '평균거래량', value: fmtVolume(p.avg_volume_20d), color: 'var(--text-muted)' },
  ]
  return (
    <div style={{
      display: 'flex', gap: '0.5rem', overflowX: 'auto', paddingBottom: '0.5rem',
      marginBottom: '0.75rem', scrollbarWidth: 'none',
    }}>
      {items.map((item, i) => (
        <div key={i} style={{
          flex: '0 0 auto', padding: '0.4rem 0.75rem',
          background: 'var(--bg-secondary)', borderRadius: '0.5rem',
          textAlign: 'center', minWidth: '80px',
        }}>
          <div style={{ fontSize: '0.6rem', color: 'var(--text-muted)', marginBottom: '0.15rem' }}>{item.label}</div>
          <div style={{ fontSize: '0.9rem', fontWeight: 700, color: item.color }}>{item.value}</div>
        </div>
      ))}
    </div>
  )
}

/* ── Overview Tab ── */
function OverviewTab({ data, levels, signals }) {
  const { prices, performance, strategy } = data
  const p = performance || {}

  // Find nearest support/resistance
  const nearestLevels = useMemo(() => {
    if (!levels?.fibonacci || !levels?.pivot_points) return null
    const current = levels.current_price
    const allLevels = [
      ...Object.entries(levels.fibonacci).map(([k, v]) => ({ label: k.replace('_', ' ').replace('fib ', 'Fib '), value: v })),
      ...Object.entries(levels.pivot_points).map(([k, v]) => ({ label: k.toUpperCase(), value: v })),
    ].sort((a, b) => a.value - b.value)

    const support = allLevels.filter(l => l.value < current).pop()
    const resistance = allLevels.filter(l => l.value > current).shift()
    return { support, resistance }
  }, [levels])

  // Latest signal
  const latestSignal = signals?.[0]

  return (
    <>
      {/* Today's Summary Card */}
      <div className="card" style={{
        marginBottom: '1rem', padding: '0.75rem 1rem',
        background: 'linear-gradient(135deg, var(--bg-secondary) 0%, rgba(99,102,241,0.05) 100%)',
        borderLeft: `4px solid ${strategy?.stance?.includes('BUY') ? '#00e676' : strategy?.stance?.includes('SELL') ? '#ff1744' : 'var(--accent)'}`,
      }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', flexWrap: 'wrap', gap: '0.75rem' }}>
          <div>
            <div style={{ fontSize: '0.7rem', color: 'var(--text-muted)', fontWeight: 600, marginBottom: '0.3rem' }}>
              오늘의 SOXL 요약
            </div>
            <div style={{ fontSize: '0.85rem', lineHeight: 1.6 }}>
              {strategy && <span>종합 판단: <b style={{ color: strategy.stance.includes('BUY') ? '#00e676' : strategy.stance.includes('SELL') ? '#ff1744' : '#ffeb3b' }}>{strategy.stance}</b></span>}
              {latestSignal && <span style={{ marginLeft: '1rem' }}>시그널 점수: <b>{latestSignal.raw_score?.toFixed(1)}</b>/100</span>}
              {p.volatility_20d_ann && <span style={{ marginLeft: '1rem' }}>변동성: <b style={{ color: p.volatility_20d_ann > 80 ? 'var(--red)' : 'var(--yellow)' }}>{p.volatility_20d_ann}%</b></span>}
            </div>
          </div>
          <div style={{ display: 'flex', gap: '1rem', fontSize: '0.78rem' }}>
            {nearestLevels?.support && (
              <div>
                <span style={{ color: 'var(--text-muted)' }}>지지: </span>
                <b style={{ color: 'var(--green)' }}>${nearestLevels.support.value}</b>
                <span style={{ color: 'var(--text-muted)', fontSize: '0.65rem' }}> ({nearestLevels.support.label})</span>
              </div>
            )}
            {nearestLevels?.resistance && (
              <div>
                <span style={{ color: 'var(--text-muted)' }}>저항: </span>
                <b style={{ color: 'var(--red)' }}>${nearestLevels.resistance.value}</b>
                <span style={{ color: 'var(--text-muted)', fontSize: '0.65rem' }}> ({nearestLevels.resistance.label})</span>
              </div>
            )}
          </div>
        </div>
      </div>

      {/* Price Chart with MA & Levels */}
      <div className="card" style={{ marginBottom: '1rem' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '0.5rem' }}>
          <h3 style={{ margin: 0 }}>📈 가격 차트</h3>
          <span style={{ fontSize: '0.7rem', color: 'var(--text-muted)' }}>
            {prices.length}일 데이터 | MA5·MA20·MA60
          </span>
        </div>
        <PriceChart prices={prices} levels={levels} />
      </div>

      {/* Two columns: Levels + Strategy */}
      <div className="card-grid" style={{ gridTemplateColumns: '1fr 1fr', marginBottom: '1rem' }}>
        {/* Fibonacci & Pivot */}
        {levels && (
          <div className="card">
            <h4 style={{ marginBottom: '0.5rem' }}>📏 핵심 레벨</h4>
            <LevelTable levels={levels} />
          </div>
        )}

        {/* Strategy Summary */}
        {strategy && (
          <div className="card" style={{
            borderLeft: `4px solid ${strategy.stance.includes('BUY') ? '#00e676' : strategy.stance.includes('SELL') ? '#ff1744' : '#ffeb3b'}`,
          }}>
            <h4 style={{ marginBottom: '0.5rem' }}>
              {STANCE_EMOJI[strategy.stance]} 종합 판단: {strategy.stance}
            </h4>
            <p style={{ color: 'var(--text-secondary)', margin: '0 0 0.5rem', fontSize: '0.8rem' }}>
              {strategy.stance_desc}
            </p>
            <ConditionBars conditions={strategy.conditions} />
            <div style={{ display: 'flex', gap: '1rem', marginTop: '0.5rem', fontSize: '0.75rem' }}>
              <span style={{ color: 'var(--green)' }}>매수 {strategy.buy_signals}개</span>
              <span style={{ color: 'var(--red)' }}>매도 {strategy.sell_signals}개</span>
            </div>
          </div>
        )}
      </div>

      {/* 52-Week Range Bar */}
      {levels?.position && (
        <div className="card" style={{ marginBottom: '1rem' }}>
          <h4 style={{ marginBottom: '0.75rem' }}>📍 52주 범위 포지션</h4>
          <RangeBar
            low={levels.fibonacci?.['52w_low']}
            high={levels.fibonacci?.['52w_high']}
            current={levels.current_price}
            levels={levels}
          />
        </div>
      )}

      {/* Risk Warnings */}
      {strategy?.risk_warnings?.length > 0 && (
        <div className="card" style={{ background: 'rgba(255,23,68,0.05)', borderLeft: '4px solid var(--red)' }}>
          <h4>⚠️ 리스크 경고</h4>
          <ul style={{ margin: '0.5rem 0 0', paddingLeft: '1.2rem', fontSize: '0.8rem', lineHeight: 1.8 }}>
            {strategy.risk_warnings.map((w, i) => (
              <li key={i} style={{ color: i < 2 ? 'var(--text-secondary)' : 'var(--red)' }}>{w}</li>
            ))}
          </ul>
        </div>
      )}
    </>
  )
}

/* ── Charts Tab (NEW - dedicated charting) ── */
function ChartsTab({ technicals, prices, levels, signals }) {
  if (!technicals) return <div className="loading">기술적 지표 데이터 없음</div>

  return (
    <>
      {/* Price + Volume Composed Chart */}
      <div className="card" style={{ marginBottom: '1rem' }}>
        <h3 style={{ marginBottom: '0.5rem' }}>📊 가격 + 거래량</h3>
        <PriceVolumeChart prices={prices} levels={levels} signals={signals} />
      </div>

      {/* RSI Chart */}
      <div className="card" style={{ marginBottom: '1rem' }}>
        <h3 style={{ marginBottom: '0.5rem' }}>📉 RSI (14)</h3>
        <RsiChart prices={prices} />
      </div>

      {/* MACD Chart */}
      <div className="card" style={{ marginBottom: '1rem' }}>
        <h3 style={{ marginBottom: '0.5rem' }}>📈 MACD</h3>
        <MacdChart prices={prices} technicals={technicals} />
      </div>

      {/* Bollinger Bands */}
      <div className="card" style={{ marginBottom: '1rem' }}>
        <h3 style={{ marginBottom: '0.5rem' }}>🎯 볼린저 밴드</h3>
        <BollingerChart prices={prices} technicals={technicals} />
      </div>

      {/* Indicator Table */}
      <div className="card">
        <h3 style={{ marginBottom: '0.5rem' }}>🔧 기술적 지표 상세</h3>
        <IndicatorTable technicals={technicals} />
      </div>
    </>
  )
}

/* ── Strategy Tab ── */
function StrategyTab({ strategy, performance, activeAlertCount = 0, onNavigate }) {
  if (!strategy) return <div className="loading">전략 데이터 없음</div>

  const rules = strategy.trading_rules || {}
  return (
    <>
      {/* Score Gauge */}
      <div className="card" style={{ marginBottom: '1rem', textAlign: 'center' }}>
        <h3 style={{ marginBottom: '0.75rem', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '0.5rem' }}>
          🎯 종합 판단
          {activeAlertCount > 0 && (
            <span onClick={() => onNavigate?.('soxl-live')}
              style={{
                fontSize: '0.65rem', padding: '0.15rem 0.5rem', borderRadius: '1rem',
                background: '#f59e0b20', color: '#f59e0b', fontWeight: 600,
                cursor: 'pointer', border: '1px solid #f59e0b44',
              }}>
              ⚡ 활성 알림 {activeAlertCount}건
            </span>
          )}
        </h3>
        <ScoreGauge
          buySignals={strategy.buy_signals}
          sellSignals={strategy.sell_signals}
          stance={strategy.stance}
        />
        <p style={{ color: 'var(--text-secondary)', marginTop: '0.5rem', fontSize: '0.85rem' }}>
          {strategy.stance_desc}
        </p>
      </div>

      {/* Conditions */}
      <div className="card" style={{ marginBottom: '1rem' }}>
        <h3>📊 현재 지표 상태</h3>
        <div style={{ display: 'grid', gap: '0.5rem', marginTop: '0.75rem' }}>
          {strategy.conditions?.map((c, i) => (
            <ConditionRow key={i} condition={c} />
          ))}
        </div>
      </div>

      {/* Entry Rules */}
      <RuleCard title="🟢 매수 규칙" rules={rules.entry_rules} color="var(--green)" />
      <RuleCard title="🔴 매도/손절 규칙" rules={rules.exit_rules} color="var(--red)" />
      <RuleCard title="💰 포지션 사이징" rules={rules.position_sizing} color="var(--accent)" />

      {/* Position Size Calculator */}
      <PositionCalculator volatility={performance?.volatility_20d_ann} currentPrice={performance?.current_price} />
    </>
  )
}

/* ── Signals Tab ── */
function SignalsTab({ signals }) {
  const [expandedIdx, setExpandedIdx] = useState(null)

  if (!signals?.length) return (
    <div className="card" style={{ textAlign: 'center', padding: '2rem' }}>
      <div style={{ fontSize: '2rem', marginBottom: '0.5rem' }}>⚡</div>
      <p style={{ color: 'var(--text-muted)' }}>시그널 이력 없음</p>
    </div>
  )

  // Signal score trend chart
  const scoreData = [...signals].reverse().map(s => ({
    date: s.date?.slice(5),
    score: s.raw_score,
    signal: s.final_signal,
  }))

  return (
    <>
      {/* Score Trend Chart */}
      <div className="card" style={{ marginBottom: '1rem' }}>
        <h3 style={{ marginBottom: '0.5rem' }}>📈 시그널 점수 추이</h3>
        <ResponsiveContainer width="100%" height={200}>
          <ComposedChart data={scoreData}>
            <CartesianGrid strokeDasharray="3 3" stroke="var(--border)" />
            <XAxis dataKey="date" tick={{ fill: 'var(--text-muted)', fontSize: 10 }} />
            <YAxis tick={{ fill: 'var(--text-muted)', fontSize: 10 }} domain={[0, 100]} />
            <Tooltip contentStyle={{ background: 'var(--bg-secondary)', border: '1px solid var(--border)', borderRadius: 8 }} />
            <ReferenceArea y1={70} y2={100} fill="rgba(0,230,118,0.05)" />
            <ReferenceArea y1={0} y2={30} fill="rgba(255,23,68,0.05)" />
            <ReferenceLine y={50} stroke="var(--text-muted)" strokeDasharray="3 3" />
            <ReferenceLine y={70} stroke="var(--green)" strokeDasharray="3 3" strokeOpacity={0.5} />
            <ReferenceLine y={30} stroke="var(--red)" strokeDasharray="3 3" strokeOpacity={0.5} />
            <Bar dataKey="score" radius={[2, 2, 0, 0]}>
              {scoreData.map((entry, i) => (
                <Cell key={i} fill={
                  entry.signal === 'BUY' || entry.signal === 'STRONG_BUY' ? 'rgba(0,230,118,0.6)' :
                  entry.signal === 'SELL' || entry.signal === 'STRONG_SELL' ? 'rgba(255,23,68,0.6)' :
                  'rgba(255,235,59,0.4)'
                } />
              ))}
            </Bar>
          </ComposedChart>
        </ResponsiveContainer>
      </div>

      {/* Signal History Table */}
      <div className="card">
        <h3 style={{ marginBottom: '0.5rem' }}>⚡ 시그널 이력 (최근 {signals.length}건)</h3>
        <div className="table-container" style={{ marginTop: '0.5rem' }}>
          <table className="table" style={{ width: '100%' }}>
            <thead>
              <tr>
                <th>날짜</th><th>시그널</th><th>점수</th>
                <th>신뢰도</th><th>HL</th><th>근거</th>
              </tr>
            </thead>
            <tbody>
              {signals.map((s, i) => (
                <tr key={i}
                  style={{ cursor: 'pointer', background: expandedIdx === i ? 'var(--bg-secondary)' : 'transparent' }}
                  onClick={() => setExpandedIdx(expandedIdx === i ? null : i)}>
                  <td style={{ whiteSpace: 'nowrap' }}>{s.date}</td>
                  <td>
                    <span style={{
                      padding: '0.15rem 0.5rem', borderRadius: '0.25rem', fontSize: '0.7rem', fontWeight: 700,
                      background: (s.final_signal || '').includes('BUY') ? 'rgba(0,230,118,0.15)' :
                        (s.final_signal || '').includes('SELL') ? 'rgba(255,23,68,0.15)' : 'rgba(255,235,59,0.15)',
                      color: (s.final_signal || '').includes('BUY') ? '#00e676' :
                        (s.final_signal || '').includes('SELL') ? '#ff1744' : '#ffeb3b',
                    }}>
                      {s.final_signal || s.raw_signal || '-'}
                    </span>
                  </td>
                  <td style={{ fontWeight: 600 }}>{s.raw_score?.toFixed(1) ?? '-'}</td>
                  <td>{s.confidence != null ? `${(s.confidence * 100).toFixed(0)}%` : '-'}</td>
                  <td>{s.hard_limit ? '🛑' : '✓'}</td>
                  <td style={{
                    fontSize: '0.75rem',
                    maxWidth: expandedIdx === i ? 'none' : '300px',
                    whiteSpace: expandedIdx === i ? 'normal' : 'nowrap',
                    overflow: 'hidden', textOverflow: 'ellipsis',
                  }}>
                    {s.rationale || '-'}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
        <div style={{ fontSize: '0.7rem', color: 'var(--text-muted)', marginTop: '0.5rem' }}>
          💡 행을 클릭하면 근거를 펼쳐볼 수 있습니다
        </div>
      </div>
    </>
  )
}

/* ── Chart Components ── */

function PriceChart({ prices, levels }) {
  // Compute MA series from prices
  const chartData = useMemo(() => {
    return prices.map((p, i) => {
      const ma5 = i >= 4 ? avg(prices.slice(i - 4, i + 1).map(x => x.close)) : null
      const ma20 = i >= 19 ? avg(prices.slice(i - 19, i + 1).map(x => x.close)) : null
      const ma60 = i >= 59 ? avg(prices.slice(i - 59, i + 1).map(x => x.close)) : null
      return { ...p, date: p.date?.slice(5), ma5, ma20, ma60 }
    })
  }, [prices])

  return (
    <ResponsiveContainer width="100%" height={350}>
      <ComposedChart data={chartData}>
        <CartesianGrid strokeDasharray="3 3" stroke="var(--border)" />
        <XAxis dataKey="date" tick={{ fill: 'var(--text-muted)', fontSize: 11 }} />
        <YAxis tick={{ fill: 'var(--text-muted)', fontSize: 11 }} domain={['auto', 'auto']} />
        <Tooltip
          contentStyle={{ background: 'var(--bg-secondary)', border: '1px solid var(--border)', borderRadius: 8, fontSize: '0.8rem' }}
          formatter={(v, name) => [name === 'close' ? `$${Number(v).toFixed(2)}` : `$${Number(v).toFixed(2)}`, name === 'close' ? '종가' : name]}
          labelFormatter={l => `${l}`}
        />
        <Legend wrapperStyle={{ fontSize: '0.7rem' }} />
        {/* Support/Resistance levels */}
        {levels?.pivot_points?.s1 && <ReferenceLine y={levels.pivot_points.s1} stroke="var(--green)" strokeDasharray="8 4" strokeOpacity={0.4} />}
        {levels?.pivot_points?.r1 && <ReferenceLine y={levels.pivot_points.r1} stroke="var(--red)" strokeDasharray="8 4" strokeOpacity={0.4} />}
        {/* Price area */}
        <Area type="monotone" dataKey="close" stroke="var(--accent)" fill="rgba(99,102,241,0.1)" strokeWidth={2} dot={false} name="종가" />
        {/* Moving averages */}
        <Line type="monotone" dataKey="ma5" stroke="#e91e63" strokeWidth={1} dot={false} name="MA5" connectNulls />
        <Line type="monotone" dataKey="ma20" stroke="#ff9800" strokeWidth={1.5} dot={false} name="MA20" connectNulls />
        <Line type="monotone" dataKey="ma60" stroke="#2196f3" strokeWidth={1.5} dot={false} name="MA60" connectNulls />
        <Brush dataKey="date" height={20} stroke="var(--border)" fill="var(--bg-secondary)" />
      </ComposedChart>
    </ResponsiveContainer>
  )
}

function PriceVolumeChart({ prices, levels, signals }) {
  const data = useMemo(() => {
    const signalMap = {}
    if (signals) signals.forEach(s => { signalMap[s.date] = s })
    return prices.map(p => ({
      ...p,
      date: p.date?.slice(5),
      fullDate: p.date,
      signal: signalMap[p.date]?.final_signal || null,
    }))
  }, [prices, signals])

  return (
    <ResponsiveContainer width="100%" height={350}>
      <ComposedChart data={data}>
        <CartesianGrid strokeDasharray="3 3" stroke="var(--border)" />
        <XAxis dataKey="date" tick={{ fill: 'var(--text-muted)', fontSize: 10 }} />
        <YAxis yAxisId="price" orientation="right" tick={{ fill: 'var(--text-muted)', fontSize: 10 }} domain={['auto', 'auto']} />
        <YAxis yAxisId="vol" orientation="left" tick={{ fill: 'var(--text-muted)', fontSize: 10 }} tickFormatter={v => `${(v / 1e6).toFixed(0)}M`} />
        <Tooltip
          contentStyle={{ background: 'var(--bg-secondary)', border: '1px solid var(--border)', borderRadius: 8 }}
          formatter={(v, name) => {
            if (name === '거래량') return [`${(Number(v) / 1e6).toFixed(1)}M`, name]
            return [`$${Number(v).toFixed(2)}`, name]
          }}
        />
        <Legend wrapperStyle={{ fontSize: '0.7rem' }} />
        {levels?.pivot_points?.pivot && <ReferenceLine yAxisId="price" y={levels.pivot_points.pivot} stroke="var(--yellow)" strokeDasharray="5 5" strokeOpacity={0.5} />}
        <Bar yAxisId="vol" dataKey="volume" name="거래량" radius={[1, 1, 0, 0]}>
          {data.map((entry, i) => (
            <Cell key={i} fill={
              entry.signal === 'BUY' || entry.signal === 'STRONG_BUY' ? 'rgba(0,230,118,0.3)' :
              entry.signal === 'SELL' || entry.signal === 'STRONG_SELL' ? 'rgba(255,23,68,0.3)' :
              'rgba(99,102,241,0.2)'
            } />
          ))}
        </Bar>
        <Line yAxisId="price" type="monotone" dataKey="close" stroke="var(--accent)" dot={false} strokeWidth={2} name="종가" />
        <Brush dataKey="date" height={20} stroke="var(--border)" fill="var(--bg-secondary)" />
      </ComposedChart>
    </ResponsiveContainer>
  )
}

function RsiChart({ prices }) {
  const data = useMemo(() => {
    return prices.map((p, i) => {
      let rsi = null
      if (i >= 14) {
        const window = prices.slice(i - 13, i + 1)
        let gains = 0, losses = 0
        for (let j = 1; j < window.length; j++) {
          const diff = window[j].close - window[j - 1].close
          if (diff > 0) gains += diff
          else losses += Math.abs(diff)
        }
        const avgGain = gains / 14
        const avgLoss = losses / 14
        rsi = avgLoss === 0 ? 100 : 100 - (100 / (1 + avgGain / avgLoss))
      }
      return { date: p.date?.slice(5), rsi: rsi ? Math.round(rsi * 10) / 10 : null }
    })
  }, [prices])

  return (
    <ResponsiveContainer width="100%" height={200}>
      <ComposedChart data={data}>
        <CartesianGrid strokeDasharray="3 3" stroke="var(--border)" />
        <XAxis dataKey="date" tick={{ fill: 'var(--text-muted)', fontSize: 10 }} />
        <YAxis tick={{ fill: 'var(--text-muted)', fontSize: 10 }} domain={[0, 100]} ticks={[0, 30, 50, 70, 100]} />
        <Tooltip contentStyle={{ background: 'var(--bg-secondary)', border: '1px solid var(--border)', borderRadius: 8 }} />
        <ReferenceArea y1={70} y2={100} fill="rgba(255,23,68,0.06)" label={{ value: '과매수', position: 'insideRight', fill: 'var(--red)', fontSize: 10 }} />
        <ReferenceArea y1={0} y2={30} fill="rgba(0,230,118,0.06)" label={{ value: '과매도', position: 'insideRight', fill: 'var(--green)', fontSize: 10 }} />
        <ReferenceLine y={50} stroke="var(--text-muted)" strokeDasharray="3 3" />
        <Line type="monotone" dataKey="rsi" stroke="#e040fb" strokeWidth={2} dot={false} connectNulls name="RSI" />
      </ComposedChart>
    </ResponsiveContainer>
  )
}

function MacdChart({ prices }) {
  // Simple MACD calculation from prices
  const data = useMemo(() => {
    const closes = prices.map(p => p.close)
    const ema12 = calcEma(closes, 12)
    const ema26 = calcEma(closes, 26)
    const macdLine = ema12.map((v, i) => v != null && ema26[i] != null ? v - ema26[i] : null)
    const macdSignal = calcEma(macdLine.filter(v => v !== null), 9)

    // Align signal with macdLine
    let sigIdx = 0
    const signalAligned = macdLine.map(v => {
      if (v === null) return null
      return sigIdx < macdSignal.length ? macdSignal[sigIdx++] : null
    })

    return prices.map((p, i) => ({
      date: p.date?.slice(5),
      macd: macdLine[i] ? Math.round(macdLine[i] * 1000) / 1000 : null,
      signal: signalAligned[i] ? Math.round(signalAligned[i] * 1000) / 1000 : null,
      histogram: macdLine[i] != null && signalAligned[i] != null ?
        Math.round((macdLine[i] - signalAligned[i]) * 1000) / 1000 : null,
    }))
  }, [prices])

  return (
    <ResponsiveContainer width="100%" height={250}>
      <ComposedChart data={data}>
        <CartesianGrid strokeDasharray="3 3" stroke="var(--border)" />
        <XAxis dataKey="date" tick={{ fill: 'var(--text-muted)', fontSize: 10 }} />
        <YAxis tick={{ fill: 'var(--text-muted)', fontSize: 10 }} />
        <Tooltip contentStyle={{ background: 'var(--bg-secondary)', border: '1px solid var(--border)', borderRadius: 8 }} />
        <Legend wrapperStyle={{ fontSize: '0.7rem' }} />
        <ReferenceLine y={0} stroke="var(--text-muted)" strokeDasharray="3 3" />
        <Bar dataKey="histogram" name="히스토그램" radius={[1, 1, 0, 0]}>
          {data.map((entry, i) => (
            <Cell key={i} fill={entry.histogram >= 0 ? 'rgba(0,230,118,0.4)' : 'rgba(255,23,68,0.4)'} />
          ))}
        </Bar>
        <Line type="monotone" dataKey="macd" stroke="#2196f3" strokeWidth={1.5} dot={false} name="MACD" connectNulls />
        <Line type="monotone" dataKey="signal" stroke="#ff9800" strokeWidth={1.5} dot={false} name="Signal" connectNulls />
      </ComposedChart>
    </ResponsiveContainer>
  )
}

function BollingerChart({ prices }) {
  const data = useMemo(() => {
    return prices.map((p, i) => {
      let bbUpper = null, bbMiddle = null, bbLower = null
      if (i >= 19) {
        const window = prices.slice(i - 19, i + 1).map(x => x.close)
        const mean = avg(window)
        const std = Math.sqrt(window.reduce((s, v) => s + (v - mean) ** 2, 0) / window.length)
        bbMiddle = mean
        bbUpper = mean + 2 * std
        bbLower = mean - 2 * std
      }
      return {
        date: p.date?.slice(5),
        close: p.close,
        bbUpper: bbUpper ? Math.round(bbUpper * 100) / 100 : null,
        bbMiddle: bbMiddle ? Math.round(bbMiddle * 100) / 100 : null,
        bbLower: bbLower ? Math.round(bbLower * 100) / 100 : null,
      }
    })
  }, [prices])

  return (
    <ResponsiveContainer width="100%" height={300}>
      <ComposedChart data={data}>
        <CartesianGrid strokeDasharray="3 3" stroke="var(--border)" />
        <XAxis dataKey="date" tick={{ fill: 'var(--text-muted)', fontSize: 10 }} />
        <YAxis tick={{ fill: 'var(--text-muted)', fontSize: 10 }} domain={['auto', 'auto']} />
        <Tooltip
          contentStyle={{ background: 'var(--bg-secondary)', border: '1px solid var(--border)', borderRadius: 8 }}
          formatter={(v) => [`$${Number(v).toFixed(2)}`, '']}
        />
        <Legend wrapperStyle={{ fontSize: '0.7rem' }} />
        <Area type="monotone" dataKey="bbUpper" stroke="rgba(255,23,68,0.3)" fill="none" strokeDasharray="4 4" name="BB Upper" connectNulls />
        <Area type="monotone" dataKey="bbLower" stroke="rgba(0,230,118,0.3)" fill="rgba(99,102,241,0.04)" strokeDasharray="4 4" name="BB Lower" connectNulls />
        <Line type="monotone" dataKey="bbMiddle" stroke="#ff9800" strokeWidth={1} dot={false} name="BB Middle" connectNulls />
        <Line type="monotone" dataKey="close" stroke="var(--accent)" strokeWidth={2} dot={false} name="종가" />
      </ComposedChart>
    </ResponsiveContainer>
  )
}

/* ── Sub-Components ── */

function LevelTable({ levels }) {
  const currentPrice = levels.current_price
  return (
    <div>
      {/* Fibonacci */}
      <div style={{ fontSize: '0.7rem', color: 'var(--text-muted)', fontWeight: 600, marginBottom: '0.3rem' }}>피보나치</div>
      <table style={{ width: '100%', fontSize: '0.78rem', marginBottom: '0.75rem' }}>
        <tbody>
          {levels.fibonacci && Object.entries(levels.fibonacci).map(([k, v]) => {
            const isNear = Math.abs(v - currentPrice) / currentPrice < 0.03
            return (
              <tr key={k} style={{ borderBottom: '1px solid var(--border)' }}>
                <td style={{ padding: '0.2rem 0', color: 'var(--text-muted)' }}>
                  {k.replace('_', ' ').replace('fib ', 'Fib ')}
                </td>
                <td style={{
                  textAlign: 'right', fontWeight: isNear ? 800 : 600,
                  color: isNear ? 'var(--accent)' : 'var(--text-primary)',
                }}>
                  ${v} {isNear ? '◄' : ''}
                </td>
              </tr>
            )
          })}
        </tbody>
      </table>
      {/* Pivot Points */}
      <div style={{ fontSize: '0.7rem', color: 'var(--text-muted)', fontWeight: 600, marginBottom: '0.3rem' }}>피봇 포인트</div>
      <table style={{ width: '100%', fontSize: '0.78rem' }}>
        <tbody>
          {levels.pivot_points && Object.entries(levels.pivot_points).map(([k, v]) => (
            <tr key={k} style={{ borderBottom: '1px solid var(--border)' }}>
              <td style={{ padding: '0.2rem 0', color: 'var(--text-muted)' }}>{k.toUpperCase()}</td>
              <td style={{
                textAlign: 'right', fontWeight: 600,
                color: k.startsWith('r') ? 'var(--red)' : k.startsWith('s') ? 'var(--green)' : 'var(--text-primary)',
              }}>${v}</td>
            </tr>
          ))}
        </tbody>
      </table>
      {levels.position && (
        <div style={{ marginTop: '0.5rem', fontSize: '0.7rem', color: 'var(--text-muted)' }}>
          고점 대비 <b style={{ color: 'var(--red)' }}>{levels.position.pct_from_52w_high}%</b> |
          저점 대비 <b style={{ color: 'var(--green)' }}>+{levels.position.pct_from_52w_low}%</b>
        </div>
      )}
    </div>
  )
}

function RangeBar({ low, high, current, levels }) {
  if (!low || !high || !current) return null
  const range = high - low
  const pct = range > 0 ? ((current - low) / range) * 100 : 50

  // Key levels to mark
  const marks = []
  if (levels?.fibonacci) {
    Object.entries(levels.fibonacci).forEach(([k, v]) => {
      if (k !== '52w_high' && k !== '52w_low') {
        marks.push({ label: k.replace('fib_', ''), value: v, pct: ((v - low) / range) * 100 })
      }
    })
  }

  return (
    <div style={{ padding: '0 0.5rem' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '0.7rem', marginBottom: '0.5rem' }}>
        <span style={{ color: 'var(--green)' }}>52주 저점: ${low}</span>
        <span style={{ fontWeight: 700, color: 'var(--accent)' }}>현재: ${current}</span>
        <span style={{ color: 'var(--red)' }}>52주 고점: ${high}</span>
      </div>
      <div style={{
        position: 'relative', height: '24px', background: 'var(--bg-secondary)',
        borderRadius: '12px', overflow: 'visible',
      }}>
        {/* Gradient fill */}
        <div style={{
          position: 'absolute', left: 0, top: 0, height: '100%',
          width: `${Math.min(pct, 100)}%`,
          background: 'linear-gradient(90deg, var(--green), var(--yellow), var(--red))',
          borderRadius: '12px', opacity: 0.3,
        }} />
        {/* Fib level marks */}
        {marks.map((m, i) => (
          <div key={i} style={{
            position: 'absolute', left: `${m.pct}%`, top: '-4px',
            width: '1px', height: '32px', background: 'var(--border)',
          }}>
            <span style={{
              position: 'absolute', top: '-16px', left: '-10px',
              fontSize: '0.55rem', color: 'var(--text-muted)', whiteSpace: 'nowrap',
            }}>{m.label}</span>
          </div>
        ))}
        {/* Current position marker */}
        <div style={{
          position: 'absolute', left: `${Math.min(pct, 100)}%`, top: '-2px',
          width: '4px', height: '28px', background: 'var(--accent)',
          borderRadius: '2px', transform: 'translateX(-2px)',
          boxShadow: '0 0 8px var(--accent)',
        }} />
      </div>
      <div style={{ textAlign: 'center', marginTop: '0.5rem', fontSize: '0.7rem', color: 'var(--text-muted)' }}>
        52주 범위 내 {pct.toFixed(1)}% 위치
      </div>
    </div>
  )
}

function ConditionBars({ conditions }) {
  if (!conditions?.length) return null
  return (
    <div style={{ display: 'grid', gap: '0.3rem' }}>
      {conditions.map((c, i) => {
        const isBullish = c.signal.includes('UNDER') || c.signal === 'BULLISH' || c.signal.includes('OVERSOLD')
        const isBearish = c.signal.includes('OVER') || c.signal === 'BEARISH'
        const color = isBullish ? '#00e676' : isBearish ? '#ff1744' : '#ffeb3b'
        return (
          <div key={i} style={{
            display: 'flex', alignItems: 'center', gap: '0.5rem', fontSize: '0.75rem',
          }}>
            <span style={{
              width: '6px', height: '6px', borderRadius: '50%', background: color, flexShrink: 0,
            }} />
            <span style={{ fontWeight: 600, minWidth: '55px', color }}>{c.indicator}</span>
            <span style={{ color: 'var(--text-muted)' }}>{c.desc}</span>
          </div>
        )
      })}
    </div>
  )
}

function ConditionRow({ condition: c }) {
  const isBullish = c.signal.includes('UNDER') || c.signal === 'BULLISH' || c.signal.includes('OVERSOLD')
  const isBearish = c.signal.includes('OVER') || c.signal === 'BEARISH'
  return (
    <div style={{
      display: 'flex', alignItems: 'center', gap: '0.75rem',
      padding: '0.5rem 0.75rem', background: 'var(--bg-secondary)', borderRadius: '0.5rem',
    }}>
      <span style={{
        padding: '0.2rem 0.5rem', borderRadius: '0.25rem', fontSize: '0.7rem', fontWeight: 700,
        minWidth: '80px', textAlign: 'center',
        background: isBearish ? 'rgba(255,23,68,0.15)' : isBullish ? 'rgba(0,230,118,0.15)' : 'rgba(255,235,59,0.15)',
        color: isBearish ? '#ff1744' : isBullish ? '#00e676' : '#ffeb3b',
      }}>
        {c.indicator}
      </span>
      <span style={{ fontWeight: 600, minWidth: '60px' }}>{typeof c.value === 'number' ? c.value : '-'}</span>
      <span style={{ fontSize: '0.8rem', color: 'var(--text-secondary)', flex: 1 }}>{c.desc}</span>
    </div>
  )
}

function ScoreGauge({ buySignals, sellSignals, stance }) {
  const total = buySignals + sellSignals
  const score = total > 0 ? (buySignals / total) * 100 : 50
  const gaugeColor = stance.includes('BUY') ? '#00e676' : stance.includes('SELL') ? '#ff1744' : '#ffeb3b'

  return (
    <div style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', gap: '2rem' }}>
      {/* Gauge bar */}
      <div style={{ width: '60%', maxWidth: '300px' }}>
        <div style={{
          height: '12px', borderRadius: '6px', background: 'var(--bg-secondary)', position: 'relative', overflow: 'hidden',
        }}>
          <div style={{
            position: 'absolute', left: 0, top: 0, height: '100%',
            width: `${score}%`, borderRadius: '6px',
            background: `linear-gradient(90deg, #ff1744, #ffeb3b, #00e676)`,
            transition: 'width 0.5s ease',
          }} />
        </div>
        <div style={{ display: 'flex', justifyContent: 'space-between', marginTop: '0.25rem', fontSize: '0.65rem', color: 'var(--text-muted)' }}>
          <span>SELL</span>
          <span>HOLD</span>
          <span>BUY</span>
        </div>
      </div>
      {/* Stance label */}
      <div style={{ textAlign: 'center' }}>
        <div style={{ fontSize: '1.5rem', fontWeight: 800, color: gaugeColor }}>{stance}</div>
        <div style={{ fontSize: '0.7rem', color: 'var(--text-muted)' }}>
          매수 {buySignals} | 매도 {sellSignals}
        </div>
      </div>
    </div>
  )
}

function RuleCard({ title, rules, color }) {
