  getSoxlOptimizeHistory,
} from '../api'
import DataFreshness from '../components/DataFreshness'

// ── Helpers ──
const fmtPct = (v) => v == null ? '—' : `${v >= 0 ? '+' : ''}${v.toFixed(2)}%`
const fmtPrice = (v) => v == null ? '—' : `$${v.toFixed(2)}`
const _fmtVol = (v) => {
  if (!v) return '—'
  if (v >= 1e9) return `${(v / 1e9).toFixed(1)}B`
  if (v >= 1e6) return `${(v / 1e6).toFixed(1)}M`
  if (v >= 1e3) return `${(v / 1e3).toFixed(0)}K`
  return v.toString()
}
const fmtTime = (ts) => {
  if (!ts) return ''
  const d = new Date(ts * 1000)
  return d.toLocaleTimeString('ko-KR', { hour: '2-digit', minute: '2-digit' })
}

const rsiColor = (v) => {
  if (v == null) return '#94a3b8'
  if (v >= 70) return '#ef4444'
  if (v <= 30) return '#22c55e'
  return '#eab308'
}

const sessionColors = {
  '장중': '#22c55e',
  '프리마켓': '#eab308',
  '애프터마켓': '#f97316',
  '장마감': '#64748b',
  '주말': '#64748b',
}

// ── SSE + Polling Hook ──
// SSE base URL must match the API proxy prefix used by api.js
const SSE_BASE = window.location.port === '8001' ? '' : '/api/vibe'

function useSoxlLive(enabled) {
  const [quote, setQuote] = useState(null)
  const [connected, setConnected] = useState(false)
  const [lastReceivedAt, setLastReceivedAt] = useState(null)
  const esRef = useRef(null)
  const pollRef = useRef(null)

  useEffect(() => {
    if (!enabled) {
      // Disconnect but keep last quote
      if (esRef.current) {
        esRef.current.close()
        esRef.current = null
      }
      if (pollRef.current) {
        clearInterval(pollRef.current)
        pollRef.current = null
      }
      setConnected(false)
      return
    }

    // Try SSE first
    const es = new EventSource(`${SSE_BASE}/soxl/live/stream`)
    esRef.current = es

    es.addEventListener('price', (e) => {
      try {
        const data = JSON.parse(e.data)
        setQuote(data)
        setConnected(true)
        setLastReceivedAt(new Date())

        // SSE recovered — stop fallback polling
        if (pollRef.current) {
          clearInterval(pollRef.current)
          pollRef.current = null
        }

        // Browser notification for alerts
        if (data.alerts?.length) {
          data.alerts.forEach(a => {
            if ('Notification' in window && Notification.permission === 'granted') {
              new Notification(`SOXL 알림: ${a.label || a.alert_type}`, {
                body: `$${a.current_price} — ${a.alert_type}: $${a.threshold}`,
                tag: `soxl-alert-${a.id}`,
              })
            }
          })
        }
      } catch { /* ignore parse errors */ }
    })

    es.onerror = () => {
      setConnected(false)
      // Fallback to polling
      if (!pollRef.current) {
        pollRef.current = setInterval(async () => {
          try {
            const q = await getSoxlLiveQuote()
            setQuote({ ...q, session: q.session || q.market_session, alerts: [] })
            setLastReceivedAt(new Date())
          } catch { /* silent */ }
        }, 15000)
      }
    }

    return () => {
      es.close()
      esRef.current = null
      if (pollRef.current) {
        clearInterval(pollRef.current)
        pollRef.current = null
      }
    }
  }, [enabled])

  return { quote, connected, lastReceivedAt }
}

